BOOL Wh_ModInit()
{
    g_unloading.store(false, std::memory_order_release);
    Wh_Log(L"File Operation Styler " WH_MOD_VERSION
           L" initialization started");

    LoadSettings();

    if (!InitializeProgressCircleUi())
    {
        return FALSE;
    }

    SkinTargets targets{};
    if (!ResolveSkinTargets(&targets) || !InstallSkinHooks(targets))
    {
        ShutdownProgressCircleUi();
        ReleaseOwnedSkinTargetModules();
        return FALSE;
    }

    Wh_Log(L"File Operation Styler " WH_MOD_VERSION
           L" initialization complete");
    return TRUE;
}

void Wh_ModBeforeUninit()
{
    if (g_unloading.exchange(true, std::memory_order_acq_rel))
    {
        return;
    }

    Wh_Log(L"File Operation Styler " WH_MOD_VERSION
           L" presentation teardown started");
    {
        std::unique_lock<std::mutex> lock(g_presentationActivationMutex);
        g_presentationActivationCondition.wait(
            lock, []
            { return g_presentationActivations == 0; });
    }
    DestroyAllProgressCircles();
    Wh_Log(L"File Operation Styler " WH_MOD_VERSION
           L" presentation teardown complete");
}

void Wh_ModUninit()
{
    ShutdownProgressCircleUi();
    {
        std::lock_guard<std::mutex> lock(g_transferSummaryMutex);
        g_transferSummaries.clear();
        ClearOperationDataBindingsLocked();
    }
    ClearSkinState();
    ReleaseOwnedSkinTargetModules();
    ShutdownSharedProgressBridge();
    ShutdownGlassBufferedPaintApi();
    ShutdownDwmApi();
    ShutdownShellMemoryApi();
    Wh_Log(L"File Operation Styler " WH_MOD_VERSION
           L" uninitialization complete");
}

BOOL Wh_ModSettingsChanged(BOOL *bReload)
{
    if (bReload)
    {
        *bReload = TRUE;
    }
    return TRUE;
}

// ==WindhawkMod==
// @id              hide-desktop-icon-text
// @name            Hide Desktop Icon Text and Shortcut Arrows
// @description     Provides options to hide icon text labels (keeping folder names) and remove shortcut arrow overlays on the desktop.
// @version         1.5.0
// @author          kivsak
// @github          https://github.com/kivsak
// @include         explorer.exe
// @architecture    x86-64
// @compilerOptions -lole32 -lshlwapi -lgdi32 -lcomctl32
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
Provides options to hide desktop icon labels (keeping folder names) and remove the shortcut arrow overlay.

### Features
* **Hide Icon Text**: Hides text labels for files and shortcuts on the desktop while preserving folder names.
* **Hide Shortcut Arrows**: Removes the standard shortcut arrow overlay live without requiring registry edits or administrator rights.

### Notes
* The shortcut arrow removal affects the entire running Explorer session because the overlay resides in the shared system image list.
* Disabling the shortcut arrow feature (or the mod itself) restores the arrows only after Explorer restarts or the icon cache refreshes.

### Known limitation
Folder detection matches the drawn text against actual desktop folder names. If a *file* has
exactly the same name as a *folder* on the desktop, that file's label will also be kept.
*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
- hide_text: true
  $name: Hide desktop icon text
  $description: Hides text labels for files and shortcuts on the desktop (keeps folder names).
- hide_arrows: true
  $name: Remove shortcut arrows
  $description: Removes the shortcut arrow overlay from icons (applies to the whole Explorer session).
*/
// ==/WindhawkModSettings==

#include <windhawk_utils.h>

#include <windows.h>
#include <commctrl.h>
#include <commoncontrols.h>
#include <shlobj.h>
#include <shlwapi.h>
#include <objbase.h>

#include <string>
#include <unordered_set>
#include <vector>

// ---------------------------------------------------------------------------
// Settings & State
// ---------------------------------------------------------------------------

struct {
    bool hide_text;
    bool hide_arrows;
} g_settings;

// Set only while the desktop SysListView32 is painting (per-thread).
thread_local bool g_isDrawingDesktop = false;

// Cache of folder display names on the desktop.
std::unordered_set<std::wstring> g_folderNames;
DWORD g_lastUpdateTick = 0;

// ---------------------------------------------------------------------------
// Window helpers
// ---------------------------------------------------------------------------

static HWND FindChild(HWND parent, LPCWSTR cls, LPCWSTR win) {
    if (!parent) return nullptr;
    return FindWindowEx(parent, nullptr, cls, win);
}

static bool IsDesktopFolderView(HWND hWnd) {
    WCHAR buf[64];

    if (!GetClassName(hWnd, buf, ARRAYSIZE(buf)) || _wcsicmp(buf, L"SysListView32")) return false;
    if (!GetWindowText(hWnd, buf, ARRAYSIZE(buf)) || _wcsicmp(buf, L"FolderView")) return false;

    HWND defView = GetAncestor(hWnd, GA_PARENT);
    if (!defView) return false;
    if (!GetClassName(defView, buf, ARRAYSIZE(buf)) || _wcsicmp(buf, L"SHELLDLL_DefView")) return false;

    HWND top = GetAncestor(defView, GA_PARENT);
    if (!top) return false;
    if ((!GetClassName(top, buf, ARRAYSIZE(buf)) || _wcsicmp(buf, L"Progman")) &&
        top != GetShellWindow()) {
        return false;
    }
    return true;
}

static HWND GetDesktopFolderView() {
    HWND lv = FindChild(FindChild(GetShellWindow(), L"SHELLDLL_DefView", L""),
                        L"SysListView32", L"FolderView");
    if (!lv) return nullptr;

    DWORD pid = 0;
    if (!GetWindowThreadProcessId(lv, &pid) || pid != GetCurrentProcessId()) return nullptr;
    return lv;
}

// ---------------------------------------------------------------------------
// Folder name cache
// ---------------------------------------------------------------------------

static void UpdateFolderCache() {
    DWORD now = GetTickCount();
    if (g_lastUpdateTick != 0 && now - g_lastUpdateTick < 1000) return;
    g_lastUpdateTick = now;

    std::unordered_set<std::wstring> fresh;

    IShellFolder* pDesktop = nullptr;
    if (SUCCEEDED(SHGetDesktopFolder(&pDesktop))) {
        IEnumIDList* pEnum = nullptr;
        if (SUCCEEDED(pDesktop->EnumObjects(nullptr, SHCONTF_FOLDERS | SHCONTF_NONFOLDERS, &pEnum))) {
            LPITEMIDLIST pidl = nullptr;
            while (pEnum->Next(1, &pidl, nullptr) == S_OK) {
                SFGAOF attr = SFGAO_FOLDER | SFGAO_STREAM;
                if (SUCCEEDED(pDesktop->GetAttributesOf(1, (LPCITEMIDLIST*)&pidl, &attr)) &&
                    (attr & SFGAO_FOLDER) && !(attr & SFGAO_STREAM)) {
                    STRRET str;
                    if (SUCCEEDED(pDesktop->GetDisplayNameOf(pidl, SHGDN_NORMAL, &str))) {
                        WCHAR name[MAX_PATH];
                        if (SUCCEEDED(StrRetToBufW(&str, pidl, name, MAX_PATH))) {
                            fresh.insert(name);
                        }
                    }
                }
                CoTaskMemFree(pidl);
            }
            pEnum->Release();
        }
        pDesktop->Release();
    }

    g_folderNames = std::move(fresh);
}

static inline bool ShouldHideLabel(LPCWSTR text, int cch) {
    if (!g_settings.hide_text) return false;
    std::wstring s(text, cch == -1 ? wcslen(text) : cch);
    return g_folderNames.count(s) == 0;
}

// ---------------------------------------------------------------------------
// Subclass
// ---------------------------------------------------------------------------

LRESULT CALLBACK DesktopListSubclass(HWND hWnd, UINT uMsg, WPARAM wParam,
                                     LPARAM lParam, DWORD_PTR dwRefData) {
    if (uMsg == WM_PAINT && g_settings.hide_text) {
        UpdateFolderCache();
        g_isDrawingDesktop = true;
        LRESULT res = DefSubclassProc(hWnd, uMsg, wParam, lParam);
        g_isDrawingDesktop = false;
        return res;
    }

    return DefSubclassProc(hWnd, uMsg, wParam, lParam);
}

// ---------------------------------------------------------------------------
// Hooks
// ---------------------------------------------------------------------------

using DrawTextW_t = decltype(&DrawTextW);
DrawTextW_t DrawTextW_Original;
int WINAPI DrawTextW_Hook(HDC hdc, LPCWSTR lpchText, int cchText, LPRECT lprc, UINT format) {
    if (g_isDrawingDesktop && lpchText && ShouldHideLabel(lpchText, cchText)) {
        return DrawTextW_Original(hdc, L"", 0, lprc, format);
    }
    return DrawTextW_Original(hdc, lpchText, cchText, lprc, format);
}

using DrawThemeTextEx_t = HRESULT (WINAPI*)(HTHEME, HDC, int, int, LPCWSTR, int, DWORD, LPRECT, const void*);
DrawThemeTextEx_t DrawThemeTextEx_Original;
HRESULT WINAPI DrawThemeTextEx_Hook(HTHEME hTheme, HDC hdc, int iPartId, int iStateId,
                                    LPCWSTR pszText, int cchText, DWORD dwTextFlags,
                                    LPRECT pRect, const void* pOptions) {
    if (g_isDrawingDesktop && pszText && ShouldHideLabel(pszText, cchText)) {
        return DrawThemeTextEx_Original(hTheme, hdc, iPartId, iStateId, L"", 0,
                                        dwTextFlags, pRect, pOptions);
    }
    return DrawThemeTextEx_Original(hTheme, hdc, iPartId, iStateId, pszText, cchText,
                                    dwTextFlags, pRect, pOptions);
}

// ---------------------------------------------------------------------------
// Shortcut arrow removal
// ---------------------------------------------------------------------------

#ifndef IDO_SHGIOI_LINK
#define IDO_SHGIOI_LINK 0x0FFFFFFE
#endif

static HICON CreateTransparentIcon(int cx, int cy) {
    if (cx <= 0 || cy <= 0) return nullptr;

    BITMAPV5HEADER bi = {};
    bi.bV5Size        = sizeof(bi);
    bi.bV5Width       = cx;
    bi.bV5Height      = cy;
    bi.bV5Planes      = 1;
    bi.bV5BitCount    = 32;
    bi.bV5Compression = BI_BITFIELDS;
    bi.bV5RedMask     = 0x00FF0000;
    bi.bV5GreenMask   = 0x0000FF00;
    bi.bV5BlueMask    = 0x000000FF;
    bi.bV5AlphaMask   = 0xFF000000;

    HDC hdc = GetDC(nullptr);
    void* bits = nullptr;
    HBITMAP hColor = CreateDIBSection(hdc, (BITMAPINFO*)&bi, DIB_RGB_COLORS, &bits, nullptr, 0);
    ReleaseDC(nullptr, hdc);
    if (!hColor) return nullptr;

    if (bits) {
        memset(bits, 0, (size_t)cx * cy * 4);
    }

    int rowBytes = ((cx + 15) / 16) * 2;
    std::vector<BYTE> maskBits((size_t)rowBytes * cy, 0xFF);
    HBITMAP hMask = CreateBitmap(cx, cy, 1, 1, maskBits.data());

    ICONINFO ii = {};
    ii.fIcon    = TRUE;
    ii.hbmColor = hColor;
    ii.hbmMask  = hMask;
    HICON hIcon = CreateIconIndirect(&ii);

    DeleteObject(hColor);
    if (hMask) DeleteObject(hMask);
    return hIcon;
}

static void HideShortcutOverlay() {
    HMODULE hShell32 = GetModuleHandle(L"shell32.dll");
    if (!hShell32) return;

    auto pSHGetImageList = (HRESULT(WINAPI*)(int, REFIID, void**))
        GetProcAddress(hShell32, "SHGetImageList");
    auto pSHGetIconOverlayIndex = (int(WINAPI*)(LPCWSTR, int))
        GetProcAddress(hShell32, "SHGetIconOverlayIndexW");
    if (!pSHGetImageList || !pSHGetIconOverlayIndex) return;

    int linkOverlay = pSHGetIconOverlayIndex(nullptr, IDO_SHGIOI_LINK);
    if (linkOverlay <= 0) return;

    static const GUID iidImageList =
        {0x46eb5926, 0x582e, 0x4017, {0x9f, 0xdf, 0xe8, 0x99, 0x8d, 0xaa, 0x09, 0x50}};

    const int sizes[] = { 1, 0, 2, 3, 4 }; // SHIL_LARGE, SHIL_SMALL, SHIL_EXTRALARGE, SHIL_SYSSMALL, SHIL_JUMBO
    for (int shil : sizes) {
        IImageList* piml = nullptr;
        if (FAILED(pSHGetImageList(shil, iidImageList, (void**)&piml)) || !piml) {
            continue;
        }

        int cx = 0, cy = 0;
        if (SUCCEEDED(piml->GetIconSize(&cx, &cy)) && cx > 0 && cy > 0) {
            if (HICON hBlank = CreateTransparentIcon(cx, cy)) {
                int idx = -1;
                if (SUCCEEDED(piml->ReplaceIcon(-1, hBlank, &idx)) && idx >= 0) {
                    piml->SetOverlayImage(idx, linkOverlay);
                }
                DestroyIcon(hBlank);
            }
        }
        piml->Release();
    }
}

// ---------------------------------------------------------------------------
// Main Hooks
// ---------------------------------------------------------------------------

using CreateWindowExW_t = decltype(&CreateWindowExW);
CreateWindowExW_t CreateWindowExW_Original;
HWND WINAPI CreateWindowExW_Hook(DWORD dwExStyle, LPCWSTR lpClassName, LPCWSTR lpWindowName,
                                 DWORD dwStyle, int X, int Y, int nWidth, int nHeight,
                                 HWND hWndParent, HMENU hMenu, HINSTANCE hInstance, PVOID lpParam) {
    HWND hWnd = CreateWindowExW_Original(dwExStyle, lpClassName, lpWindowName, dwStyle,
                                         X, Y, nWidth, nHeight, hWndParent, hMenu,
                                         hInstance, lpParam);
    if (hWnd && IsDesktopFolderView(hWnd)) {
        WindhawkUtils::SetWindowSubclassFromAnyThread(hWnd, DesktopListSubclass, 0);
    }
    return hWnd;
}

void LoadSettings() {
    g_settings.hide_text = Wh_GetIntSetting(L"hide_text") != 0;
    g_settings.hide_arrows = Wh_GetIntSetting(L"hide_arrows") != 0;
}

// ---------------------------------------------------------------------------
// Lifecycle
// ---------------------------------------------------------------------------

BOOL Wh_ModInit() {
    LoadSettings();

    WindhawkUtils::SetFunctionHook(CreateWindowExW, CreateWindowExW_Hook, &CreateWindowExW_Original);

    if (HMODULE hUser32 = GetModuleHandle(L"user32.dll")) {
        if (auto p = (DrawTextW_t)GetProcAddress(hUser32, "DrawTextW"))
            WindhawkUtils::SetFunctionHook(p, DrawTextW_Hook, &DrawTextW_Original);
    }

    if (HMODULE hUxTheme = GetModuleHandle(L"uxtheme.dll")) {
        if (auto p = (DrawThemeTextEx_t)GetProcAddress(hUxTheme, "DrawThemeTextEx"))
            WindhawkUtils::SetFunctionHook(p, DrawThemeTextEx_Hook, &DrawThemeTextEx_Original);
    }

    if (g_settings.hide_arrows) {
        HideShortcutOverlay();
    }

    return TRUE;
}

void Wh_ModAfterInit() {
    if (g_settings.hide_arrows) {
        SHChangeNotify(SHCNE_ASSOCCHANGED, SHCNF_IDLIST, nullptr, nullptr);
    }

    if (HWND hDesktop = GetDesktopFolderView()) {
        WindhawkUtils::SetWindowSubclassFromAnyThread(hDesktop, DesktopListSubclass, 0);
        int count = ListView_GetItemCount(hDesktop);
        if (count > 0) {
            ListView_RedrawItems(hDesktop, 0, count - 1);
        }
        InvalidateRect(hDesktop, nullptr, TRUE);
        UpdateWindow(hDesktop);
    }
}

void Wh_ModUninit() {
    if (HWND hDesktop = GetDesktopFolderView()) {
        WindhawkUtils::RemoveWindowSubclassFromAnyThread(hDesktop, DesktopListSubclass);
        InvalidateRect(hDesktop, nullptr, TRUE);
        UpdateWindow(hDesktop);
    }
}

BOOL Wh_ModSettingsChanged(BOOL* bReload) {
    *bReload = TRUE;
    return TRUE;
}

// ==WindhawkMod==
// @id              hide-dotfiles-explorer
// @name            Hide Dotfiles (Explorer only)
// @description     Hide dotfiles and folders starting with . in Windows Explorer and Desktop
// @version         1.0.1
// @author          @danalec
// @github          https://github.com/danalec
// @include         explorer.exe
// @compilerOptions -lcomctl32 -lole32 -loleaut32 -lshell32 -lshlwapi
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
This mod hides files and folders starting with a dot (.) in Windows Explorer and Desktop, similar to Unix/Linux systems.

![Screenshot](https://i.imgur.com/y75mPVQ.png)

## How It Works
This mod **filters files directly from directory listings** at the system level.
It does **not** modify file attributes (like the "hidden" attribute) and **does not** depend on Windows Explorer's "Show hidden files" setting.
Files are completely hidden from view regardless of Explorer's hidden file visibility settings.

## Key Benefits
- **Independent of Explorer settings**: Works regardless of whether "Show hidden files" is enabled or disabled
- **No file attribute modification**: Files remain unchanged on disk
- **System-wide filtering**: Affects all Explorer views and file dialogs

## Configuration
You can exclude specific files from being hidden using the dotfile whitelist, or specify 
additional files to always hide regardless of whether they start with a dot.

### Display Modes
Choose how dotfiles should be handled:
- **Never show**: Files are completely hidden from directory listings (default)
- **Show as hidden**: Files are shown with the hidden attribute (like Unix `ls -a`)
- **Show as system**: Files are shown with both hidden and system attributes

### Filename Matching
- **Case-insensitive**: Filenames are matched regardless of case (e.g., `.Gitignore` will match `.gitignore`)
- **Pattern matching**: Supports wildcards using Windows pattern matching syntax
  - `*` matches zero or more characters
  - `?` matches exactly one character
  - Examples: `.env*` matches `.env`, `.env.local`, `.env.production`

### Settings
- **Display Mode**: How to handle dotfiles (Never show, Show as hidden, Show as system)
- **Dotfile Whitelist**: List of dotfile patterns to show (e.g., `.gitignore`, `.env*`, `.*.config`)
- **Always Hide**: List of filename patterns to always hide, even if they don't start with a dot (e.g., `desktop.ini`, `Thumbs.db`, `*.tmp`)

Examples:
- To show `.gitignore`: add `.gitignore` to dotfile whitelist
- To show all `.env*` files: add `.env*` to dotfile whitelist
- To hide `desktop.ini`: add `desktop.ini` to always-hide list
- To hide all `.tmp` files: add `*.tmp` to always-hide list
- `.env.local` will be shown if `.env*` is whitelisted

## Important Notes
- **No file attributes are modified** - hidden files retain their original attributes
- **Independent of Explorer settings** - works regardless of "Show hidden files" setting
- **Other applications** can still access these files normally
- **Command Prompt/PowerShell** will still show these files unless specifically filtered
*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
- displayMode: neverShow
  $name: Display Mode
  $description: How to handle dotfiles in directory listings
  $options:
  - neverShow: Never show files (completely hidden)
  - showAsHidden: Show files as hidden (with hidden attribute)
  - showAsSystem: Show files as system (with hidden+system attributes)
- dotfileWhitelist: [""]
  $name: Dotfile Whitelist
  $description: List of dotfile patterns to show
- alwaysHide: [""]
  $name: Always Hide
  $description: List of filename patterns to always hide regardless of dotfile status
*/
// ==/WindhawkModSettings==

#include <windows.h>
#include <shlobj.h>
#include <shlwapi.h>
#include <shobjidl.h>
#include <winternl.h>
#include <vector>
#include <string>
#include <algorithm>

enum class DisplayMode {
    NeverShow,
    ShowAsHidden,
    ShowAsSystem
};

struct {
    DisplayMode displayMode = DisplayMode::NeverShow;
    std::vector<std::wstring> dotfileWhitelist;
    std::vector<std::wstring> alwaysHide;
} g_settings;

typedef NTSTATUS (NTAPI* NtQueryDirectoryFile_t)(
    HANDLE FileHandle,
    HANDLE Event,
    PIO_APC_ROUTINE ApcRoutine,
    PVOID ApcContext,
    PIO_STATUS_BLOCK IoStatusBlock,
    PVOID FileInformation,
    ULONG Length,
    FILE_INFORMATION_CLASS FileInformationClass,
    BOOLEAN ReturnSingleEntry,
    PUNICODE_STRING FileName,
    BOOLEAN RestartScan
);

NtQueryDirectoryFile_t NtQueryDirectoryFile_Original;

typedef NTSTATUS (NTAPI* NtQueryDirectoryFileEx_t)(
    HANDLE FileHandle,
    HANDLE Event,
    PIO_APC_ROUTINE ApcRoutine,
    PVOID ApcContext,
    PIO_STATUS_BLOCK IoStatusBlock,
    PVOID FileInformation,
    ULONG Length,
    FILE_INFORMATION_CLASS FileInformationClass,
    ULONG QueryFlags,
    PUNICODE_STRING FileName
);

NtQueryDirectoryFileEx_t NtQueryDirectoryFileEx_Original;

void ParseSettings() {
    g_settings.dotfileWhitelist.clear();
    g_settings.alwaysHide.clear();
    
    PCWSTR displayModeStr = Wh_GetStringSetting(L"displayMode");
    if (wcscmp(displayModeStr, L"showAsHidden") == 0) {
        g_settings.displayMode = DisplayMode::ShowAsHidden;
    } else if (wcscmp(displayModeStr, L"showAsSystem") == 0) {
        g_settings.displayMode = DisplayMode::ShowAsSystem;
    } else {
        g_settings.displayMode = DisplayMode::NeverShow;
    }
    Wh_FreeStringSetting(displayModeStr);
    
    auto loadSettingList = [](const wchar_t* settingName, std::vector<std::wstring>& target) {
        for (int i = 0;; i++) {
            PCWSTR item = Wh_GetStringSetting(settingName, i);
            if (!*item) {
                Wh_FreeStringSetting(item);
                break;
            }
            target.emplace_back(item);
            Wh_FreeStringSetting(item);
        }
    };
    
    loadSettingList(L"dotfileWhitelist[%d]", g_settings.dotfileWhitelist);
    loadSettingList(L"alwaysHide[%d]", g_settings.alwaysHide);
}

bool ShouldHideFile(std::wstring_view fileName) noexcept {
    if (fileName.empty()) return false;
    
    if (fileName == L"." || fileName == L"..") {
        return false;
    }
    
    auto matchesPattern = [](std::wstring_view name, const std::vector<std::wstring>& patterns) noexcept -> bool {
        std::wstring temp(name);
        return std::ranges::any_of(patterns, [&temp](const std::wstring& pattern) {
            return PathMatchSpecW(temp.c_str(), pattern.c_str()) != FALSE;
        });
    };
    
    if (fileName[0] == L'.') {
        return !matchesPattern(fileName, g_settings.dotfileWhitelist);
    }
    
    return matchesPattern(fileName, g_settings.alwaysHide);
}

template<typename FileInfoType>
void FilterFilesInDirectory(void* FileInformation, ULONG_PTR* bytesReturned) noexcept {
    if (!FileInformation || !bytesReturned || *bytesReturned == 0) {
        return;
    }
    
    if (g_settings.displayMode == DisplayMode::NeverShow) {
        auto* currentEntry = static_cast<FileInfoType*>(FileInformation);
        auto* writeEntry = currentEntry;
        ULONG_PTR totalBytesRead = 0;
        ULONG_PTR totalBytesWritten = 0;
        
        const auto* const bufferEnd = reinterpret_cast<const BYTE*>(FileInformation) + *bytesReturned;
        
        while (totalBytesRead < *bytesReturned) {
            const ULONG nextEntryOffset = currentEntry->NextEntryOffset;
            const ULONG currentEntrySize = nextEntryOffset ? nextEntryOffset : (*bytesReturned - totalBytesRead);
            
            const ULONG fileNameLength = currentEntry->FileNameLength / sizeof(WCHAR);
            const std::wstring_view fileName(currentEntry->FileName, fileNameLength);
            
            const bool shouldHide = fileNameLength > 0 && ShouldHideFile(fileName);
            
            if (!shouldHide) {
                if (writeEntry != currentEntry) {
                    std::memmove(writeEntry, currentEntry, currentEntrySize);
                }
                totalBytesWritten += currentEntrySize;
                writeEntry = reinterpret_cast<FileInfoType*>(reinterpret_cast<BYTE*>(writeEntry) + currentEntrySize);
            }
            
            totalBytesRead += currentEntrySize;
            
            if (nextEntryOffset == 0 || 
                reinterpret_cast<const BYTE*>(currentEntry) + nextEntryOffset >= bufferEnd) {
                break;
            }
            
            currentEntry = reinterpret_cast<FileInfoType*>(
                reinterpret_cast<BYTE*>(currentEntry) + nextEntryOffset);
        }
        
        if (totalBytesWritten > 0) {
            auto* lastEntry = static_cast<FileInfoType*>(FileInformation);
            while (lastEntry->NextEntryOffset && 
                   reinterpret_cast<BYTE*>(lastEntry) + lastEntry->NextEntryOffset < 
                   reinterpret_cast<BYTE*>(FileInformation) + totalBytesWritten) {
                lastEntry = reinterpret_cast<FileInfoType*>(
                    reinterpret_cast<BYTE*>(lastEntry) + lastEntry->NextEntryOffset);
            }
            lastEntry->NextEntryOffset = 0;
        }
        
        *bytesReturned = totalBytesWritten;
    } else if constexpr (requires(FileInfoType t) { t.FileAttributes; }) {
            auto* currentEntry = static_cast<FileInfoType*>(FileInformation);
            ULONG_PTR totalBytesRead = 0;
            const auto* const bufferEnd = reinterpret_cast<const BYTE*>(FileInformation) + *bytesReturned;
            
            while (totalBytesRead < *bytesReturned) {
                const ULONG nextEntryOffset = currentEntry->NextEntryOffset;
                const ULONG currentEntrySize = nextEntryOffset ? nextEntryOffset : (*bytesReturned - totalBytesRead);
                
                const ULONG fileNameLength = currentEntry->FileNameLength / sizeof(WCHAR);
                const std::wstring_view fileName(currentEntry->FileName, fileNameLength);
                
                if (fileNameLength > 0 && ShouldHideFile(fileName)) {
                    DWORD newAttributes = 0;
                    switch (g_settings.displayMode) {
                        case DisplayMode::ShowAsHidden:
                            newAttributes = FILE_ATTRIBUTE_HIDDEN;
                            break;
                        case DisplayMode::ShowAsSystem:
                            newAttributes = FILE_ATTRIBUTE_HIDDEN | FILE_ATTRIBUTE_SYSTEM;
                            break;
                        default:
                            break;
                    }
                    
                    if (newAttributes != 0) {
                        currentEntry->FileAttributes |= newAttributes;
                    }
                }
                
                totalBytesRead += currentEntrySize;
                
                if (nextEntryOffset == 0 || 
                    reinterpret_cast<const BYTE*>(currentEntry) + nextEntryOffset >= bufferEnd) {
                    break;
                }
                
                currentEntry = reinterpret_cast<FileInfoType*>(
                    reinterpret_cast<BYTE*>(currentEntry) + nextEntryOffset);
            }
        }
}

void ProcessDirectoryListing(LPVOID FileInformation, FILE_INFORMATION_CLASS FileInformationClass, ULONG_PTR* bytesReturned) noexcept {
    switch (FileInformationClass) {
        case FileDirectoryInformation:
            FilterFilesInDirectory<FILE_DIRECTORY_INFORMATION>(FileInformation, bytesReturned);
            break;
        case FileFullDirectoryInformation:
            FilterFilesInDirectory<FILE_FULL_DIR_INFORMATION>(FileInformation, bytesReturned);
            break;
        case FileBothDirectoryInformation:
            FilterFilesInDirectory<FILE_BOTH_DIR_INFORMATION>(FileInformation, bytesReturned);
            break;
        case FileNamesInformation:
            FilterFilesInDirectory<FILE_NAMES_INFORMATION>(FileInformation, bytesReturned);
            break;
        case FileIdBothDirectoryInformation:
            FilterFilesInDirectory<FILE_ID_BOTH_DIR_INFORMATION>(FileInformation, bytesReturned);
            break;
        case FileIdFullDirectoryInformation:
            FilterFilesInDirectory<FILE_ID_FULL_DIR_INFORMATION>(FileInformation, bytesReturned);
            break;
        default:
            break;
    }
}

NTSTATUS NTAPI NtQueryDirectoryFile_Hook(
    HANDLE FileHandle,
    HANDLE Event,
    PIO_APC_ROUTINE ApcRoutine,
    PVOID ApcContext,
    PIO_STATUS_BLOCK IoStatusBlock,
    PVOID FileInformation,
    ULONG Length,
    FILE_INFORMATION_CLASS FileInformationClass,
    BOOLEAN ReturnSingleEntry,
    PUNICODE_STRING FileName,
    BOOLEAN RestartScan) noexcept {
    
    const NTSTATUS status = NtQueryDirectoryFile_Original(
        FileHandle, Event, ApcRoutine, ApcContext, IoStatusBlock,
        FileInformation, Length, FileInformationClass,
        ReturnSingleEntry, FileName, RestartScan);
    
    if (NT_SUCCESS(status) && IoStatusBlock && FileInformation) {
        ULONG_PTR bytesReturned = IoStatusBlock->Information;
        ProcessDirectoryListing(FileInformation, FileInformationClass, &bytesReturned);
        IoStatusBlock->Information = bytesReturned;
    }
    
    return status;
}

NTSTATUS NTAPI NtQueryDirectoryFileEx_Hook(
    HANDLE FileHandle,
    HANDLE Event,
    PIO_APC_ROUTINE ApcRoutine,
    PVOID ApcContext,
    PIO_STATUS_BLOCK IoStatusBlock,
    PVOID FileInformation,
    ULONG Length,
    FILE_INFORMATION_CLASS FileInformationClass,
    ULONG QueryFlags,
    PUNICODE_STRING FileName) noexcept {
    
    const NTSTATUS status = NtQueryDirectoryFileEx_Original(
        FileHandle, Event, ApcRoutine, ApcContext, IoStatusBlock,
        FileInformation, Length, FileInformationClass,
        QueryFlags, FileName);
    
    if (NT_SUCCESS(status) && IoStatusBlock && FileInformation) {
        ULONG_PTR bytesReturned = IoStatusBlock->Information;
        ProcessDirectoryListing(FileInformation, FileInformationClass, &bytesReturned);
        IoStatusBlock->Information = bytesReturned;
    }
    
    return status;
}

BOOL Wh_ModInit() {
    ParseSettings();
    
    const HMODULE hNtDll = GetModuleHandleW(L"ntdll.dll");
    if (!hNtDll) {
        return FALSE;
    }
    
    NtQueryDirectoryFile_Original = reinterpret_cast<NtQueryDirectoryFile_t>(
        GetProcAddress(hNtDll, "NtQueryDirectoryFile"));
    NtQueryDirectoryFileEx_Original = reinterpret_cast<NtQueryDirectoryFileEx_t>(
        GetProcAddress(hNtDll, "NtQueryDirectoryFileEx"));
    
    if (!NtQueryDirectoryFile_Original || !NtQueryDirectoryFileEx_Original) {
        return FALSE;
    }
    
    return Wh_SetFunctionHook(reinterpret_cast<void*>(NtQueryDirectoryFile_Original), 
                              reinterpret_cast<void*>(NtQueryDirectoryFile_Hook), 
                              reinterpret_cast<void**>(&NtQueryDirectoryFile_Original)) &&
           Wh_SetFunctionHook(reinterpret_cast<void*>(NtQueryDirectoryFileEx_Original), 
                              reinterpret_cast<void*>(NtQueryDirectoryFileEx_Hook), 
                              reinterpret_cast<void**>(&NtQueryDirectoryFileEx_Original));
}

void Wh_ModSettingsChanged() {
    ParseSettings();
}

// ==WindhawkMod==
// @id              invisible-borders
// @name            Invisible Window Borders
// @description     Makes window borders invisible while keeping rounded corners
// @version         1.0.0
// @author          Bo0ii
// @github          https://github.com/Bo0ii
// @homepage        https://github.com/Bo0ii/windhawk-mods
// @include         *
// @exclude         devenv.exe
// @compilerOptions -ldwmapi -luser32
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
# Invisible Window Borders

Makes window borders invisible while preserving rounded corners.

![Comparison](https://raw.githubusercontent.com/Bo0ii/windhawk-mods/main/invisible-borders/onoff.png)

## Features

- **Invisible Borders**: Removes border color while keeping frame structure
- **Preserves Rounded Corners**: Keeps window frame intact for corner rendering
- **Universal**: Works with all applications
- **Lightweight**: Minimal performance impact

## Compatibility

- Windows 10 (version 1809 and later)
- Windows 11 (all versions)
- Requires DWM (Desktop Window Manager) to be enabled

## Support

Report issues at: https://github.com/Bo0ii/windhawk-mods/issues

## License

MIT License - Feel free to modify and distribute
*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
- SpecialWindows: false
  $name: Apply to Special Windows
  $description: Also apply to special windows like dialogs
*/
// ==/WindhawkModSettings==

#include <dwmapi.h>
#include <windhawk_api.h>

// Special DWM color values
#ifndef DWMWA_COLOR_NONE
#define DWMWA_COLOR_NONE 0xFFFFFFFE
#endif

const COLORREF BorderInvisible = DWMWA_COLOR_NONE;  // No border color
const COLORREF ColorDefault = DWMWA_COLOR_DEFAULT;

bool SpecialWindows = false;

BOOL IsValidWindow(HWND hWnd) {
    DWORD dwStyle = GetWindowLongPtr(hWnd, GWL_STYLE);
    // Better exclude context menus
    return (dwStyle & WS_THICKFRAME) == WS_THICKFRAME ||
           (dwStyle & WS_CAPTION) == WS_CAPTION ||
           (SpecialWindows && (dwStyle & WS_OVERLAPPED) == WS_OVERLAPPED && (dwStyle & WS_POPUP) != WS_POPUP);
}

using DwmSetWindowAttribute_t = decltype(&DwmSetWindowAttribute);
DwmSetWindowAttribute_t DwmSetWindowAttribute_orig;
HRESULT WINAPI DwmSetWindowAttribute_hook(HWND hwnd, DWORD dwAttribute, LPCVOID pvAttribute, DWORD cbAttribute) {
    if (dwAttribute == DWMWA_BORDER_COLOR && IsValidWindow(hwnd)) {
        Wh_Log(L"Intercepted DWMWA_BORDER_COLOR - setting to invisible");
        // Override with invisible border
        return DwmSetWindowAttribute_orig(hwnd, dwAttribute, &BorderInvisible, sizeof(BorderInvisible));
    }

    return DwmSetWindowAttribute_orig(hwnd, dwAttribute, pvAttribute, cbAttribute);
}

void SetBorderInvisible(HWND hWnd)
{
    if (!IsValidWindow(hWnd))
        return;

    Wh_Log(L"Setting invisible border");
    DwmSetWindowAttribute_orig(hWnd, DWMWA_BORDER_COLOR, &BorderInvisible, sizeof(BorderInvisible));
}

using DefWindowProcA_t = decltype(&DefWindowProcA);
DefWindowProcA_t DefWindowProcA_orig;
LRESULT WINAPI DefWindowProcA_hook(HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam)
{
    LRESULT result = DefWindowProcA_orig(hWnd, uMsg, wParam, lParam);

    switch (uMsg) {
        case WM_ACTIVATE:
        case WM_NCACTIVATE:
        case WM_DWMCOLORIZATIONCOLORCHANGED:
            SetBorderInvisible(hWnd);
            break;
    }

    return result;
}

using DefWindowProcW_t = decltype(&DefWindowProcW);
DefWindowProcW_t DefWindowProcW_orig;
LRESULT WINAPI DefWindowProcW_hook(HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam)
{
    LRESULT result = DefWindowProcW_orig(hWnd, uMsg, wParam, lParam);

    switch (uMsg) {
        case WM_ACTIVATE:
        case WM_NCACTIVATE:
        case WM_DWMCOLORIZATIONCOLORCHANGED:
            SetBorderInvisible(hWnd);
            break;
    }

    return result;
}

using DefDlgProcA_t = decltype(&DefDlgProcA);
DefDlgProcA_t DefDlgProcA_orig;
LRESULT WINAPI DefDlgProcA_hook(HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam)
{
    LRESULT result = DefDlgProcA_orig(hWnd, uMsg, wParam, lParam);

    switch (uMsg) {
        case WM_NCACTIVATE:
            SetBorderInvisible(hWnd);
            break;
    }

    return result;
}

using DefDlgProcW_t = decltype(&DefDlgProcW);
DefDlgProcW_t DefDlgProcW_orig;
LRESULT WINAPI DefDlgProcW_hook(HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam)
{
    LRESULT result = DefDlgProcW_orig(hWnd, uMsg, wParam, lParam);

    switch (uMsg) {
        case WM_NCACTIVATE:
            SetBorderInvisible(hWnd);
            break;
    }

    return result;
}

BOOL CALLBACK EnableEnumWindowsCallback(HWND hWnd, LPARAM lParam) {
    DWORD pid = lParam;

    DWORD wPid = 0;
    GetWindowThreadProcessId(hWnd, &wPid);

    if (pid == wPid) {
        SetBorderInvisible(hWnd);
    }

    return TRUE;
}

BOOL CALLBACK DisableEnumWindowsCallback(HWND hWnd, LPARAM lParam) {
    DWORD pid = lParam;
    DWORD wPid = 0;
    GetWindowThreadProcessId(hWnd, &wPid);

    if (pid == wPid && IsValidWindow(hWnd))
        DwmSetWindowAttribute_orig(hWnd, DWMWA_BORDER_COLOR, &ColorDefault, sizeof(ColorDefault));

    return TRUE;
}

BOOL Wh_ModInit() {
    Wh_Log(L"Init - Invisible Borders");

    SpecialWindows = Wh_GetIntSetting(L"SpecialWindows");

    Wh_SetFunctionHook(
        (void *)DwmSetWindowAttribute,
        (void *)DwmSetWindowAttribute_hook,
        (void **)&DwmSetWindowAttribute_orig);

    Wh_SetFunctionHook(
        (void *)DefWindowProcW,
        (void *)DefWindowProcW_hook,
        (void **)&DefWindowProcW_orig
    );

    Wh_SetFunctionHook(
        (void *)DefWindowProcA,
        (void *)DefWindowProcA_hook,
        (void **)&DefWindowProcA_orig
    );

    Wh_SetFunctionHook(
        (void *)DefDlgProcW,
        (void *)DefDlgProcW_hook,
        (void **)&DefDlgProcW_orig
    );

    Wh_SetFunctionHook(
        (void *)DefDlgProcA,
        (void *)DefDlgProcA_hook,
        (void **)&DefDlgProcA_orig
    );

    return TRUE;
}

void Wh_ModAfterInit() {
    Wh_Log(L"AfterInit - Applying invisible borders");
    EnumWindows(EnableEnumWindowsCallback, GetCurrentProcessId());
}

void Wh_ModBeforeUninit() {
    Wh_Log(L"BeforeUninit - Restoring default borders");
    EnumWindows(DisableEnumWindowsCallback, GetCurrentProcessId());
}

void Wh_ModSettingsChanged() {
    Wh_Log(L"SettingsChanged");
    EnumWindows(DisableEnumWindowsCallback, GetCurrentProcessId());
    SpecialWindows = Wh_GetIntSetting(L"SpecialWindows");
    EnumWindows(EnableEnumWindowsCallback, GetCurrentProcessId());
}

// ==WindhawkMod==
// @id              shake-to-find-cursor
// @name            Shake to Find Cursor
// @description     Temporarily enlarges the mouse cursor when you shake the mouse, like macOS "Shake to locate"
// @version         1.4.1
// @author          Darius Varnelis
// @github          https://github.com/Darius-Varnelis
// @include         windhawk.exe
// @compilerOptions -luser32 -lgdi32 -lshell32 -ladvapi32 -lshcore
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
# Shake to Find Cursor

![Shake to Find Cursor demo](https://raw.githubusercontent.com/Darius-Varnelis/shake-to-find-cursor/main/shake-to-find.gif)

Shake the mouse (or swipe back and forth on the touchpad) and the cursor grows
so you can spot it instantly. Stop shaking and it shrinks back.

## How it works

* Runs as a *tool mod* in its own background process, so it never touches
  Explorer.
* Listens to raw mouse input: no polling, no CPU use while the mouse is idle,
  and it can't add input lag the way a low-level mouse hook can.
* A shake means the cursor travelled a long way (**Shake distance**) while
  staying inside a small area (**Back-and-forth ratio**) within the
  **Time window**.
* Enlarging replaces the real system cursors with bigger versions loaded from
  your current cursor scheme's files at the target size. The big cursor *is*
  the pointer: no overlay window, no trailing, and it keeps your cursor
  style and colour. The normal cursors are restored the same way Control Panel
  applies a scheme.
* Keep shaking and the cursor keeps growing, slower and slower: each further
  step of the same size takes twice as long as the previous one. By default
  it stops at the height of your screen, which takes hours of shaking.
* The grow and shrink animations are time-based and run at your display's
  refresh rate. The cursor that's on screen is resized every frame; the other
  cursor types are resized a few at a time within a small time budget per
  frame, so each frame stays cheap.
* Animated cursors (.ani) grow and shrink smoothly too, and keep animating
  while enlarged: the mod plays the animation itself, one frame at a time at
  the current size, and hands back to the real cursor when it's done.

## vs. macOS magnifying cursor

The catalog already has [macOS magnifying cursor](https://windhawk.net/mods/mac-magnifying-cursor),
which does something similar but works differently: it hides the system
cursors and draws a scaled copy in its own overlay window, polling the cursor
position every 16-40 ms. This mod instead replaces the real system cursors
with bigger renders of your own cursor scheme, driven by raw input rather
than polling. In practice that means no overlay lag or trailing, the enlarged
cursor keeps your actual cursor style and colour, and there's no CPU cost
while the mouse is idle. Don't enable both at once - they'll fight over the
system cursors.

## Notes

* Very large cursors (a large pointer size in Windows' Accessibility
  settings, a large cursor scheme, or a big enlargement) take Windows longer
  to draw at each step, so the grow and shrink animations may be less smooth.
* Apps that draw their own custom cursor keep their small one.
* Cursor files contain images of up to 256 px, so past that the cursor is
  upscaled and gets softer.
* If the mod's process is killed while the cursor is big, the normal cursors
  are restored the next time the mod starts (re-applying a pointer scheme in
  Mouse Properties also fixes it).
* Raw input may not reach the mod while an elevated window (Task Manager, a
  UAC prompt, an installer) has focus, depending on Windows version. If so, a
  shake over such a window won't be detected until focus moves elsewhere.
*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
- scalePercent: 400
  $name: Enlarged size (%)
  $description: Size of the enlarged cursor relative to its normal size (400 = 4x bigger) (default = 400)
- keepGrowing: 50
  $name: Keep growing while shaking (%)
  $description: >-
    If you keep shaking after the first enlargement, the cursor keeps growing.
    It grows by this much in the first second, then slower and slower (the next
    step of the same size takes 2 s, then 4 s, 8 s and so on).
    0 = stop at the first enlargement (default = 50)
- sizeLimit: 0
  $name: Size limit (px)
  $description: The cursor never grows past this size (0 = the height of your screen) (default = 0)
- shakeDistance: 800
  $name: Shake distance (px)
  $description: How far the cursor has to travel within the time window. Lower = easier to trigger (default = 800)
- shakeRatio: 350
  $name: Back-and-forth ratio (%)
  $description: >-
    Distance travelled divided by the diagonal of the area the cursor stayed in.
    A straight swipe is about 100, four strokes left and right about 400.
    Lower = easier to trigger, but fast normal movements may start to count as shakes (default = 350)
- shakeWindow: 1000
  $name: Time window (ms)
  $description: How much recent movement is looked at when detecting a shake (default = 1000)
- holdTime: 500
  $name: Stay enlarged for (ms)
  $description: How long the cursor stays big after you stop shaking (default = 500)
- growDuration: 150
  $name: Grow animation (ms)
  $description: How long the cursor takes to grow (0 = instant) (default = 150)
- shrinkDuration: 250
  $name: Shrink animation (ms)
  $description: How long the cursor takes to shrink back (0 = instant) (default = 250)
- disableInFullscreen: true
  $name: Disable in fullscreen apps and games
  $description: Don't enlarge the cursor while a fullscreen app, game or presentation is in the foreground (default = on)
*/
// ==/WindhawkModSettings==

#include <windows.h>
#include <shellapi.h>
#include <shellscalingapi.h>

#include <algorithm>
#include <cmath>
#include <deque>
#include <atomic>
#include <memory>
#include <vector>

////////////////////////////////////////////////////////////////////////////////
// Settings

struct Settings {
    int scalePercent = 400;
    int keepGrowingPercent = 50;
    int sizeLimit = 0;  // 0 = height of the screen.
    int shakeDistance = 800;
    int shakeRatioPercent = 350;
    int shakeWindowMs = 1000;
    int holdMs = 500;
    int growMs = 150;
    int shrinkMs = 250;
    bool disableInFullscreen = true;
};

// Only accessed on the worker thread once it's running.
Settings g_settings;

int PositiveIntSetting(PCWSTR name, int fallback, int minValue, int maxValue) {
    int value = Wh_GetIntSetting(name);
    if (value <= 0) {
        value = fallback;
    }
    return std::clamp(value, minValue, maxValue);
}

Settings LoadSettings() {
    Settings s;
    s.scalePercent = PositiveIntSetting(L"scalePercent", 400, 110, 1000);
    s.keepGrowingPercent = std::clamp(Wh_GetIntSetting(L"keepGrowing"), 0, 500);
    const int sizeLimit = Wh_GetIntSetting(L"sizeLimit");
    s.sizeLimit = sizeLimit <= 0 ? 0 : std::clamp(sizeLimit, 32, 4096);
    s.shakeDistance = PositiveIntSetting(L"shakeDistance", 800, 100, 20000);
    s.shakeRatioPercent = PositiveIntSetting(L"shakeRatio", 350, 150, 2000);
    s.shakeWindowMs = PositiveIntSetting(L"shakeWindow", 1000, 200, 5000);
    s.holdMs = std::clamp(Wh_GetIntSetting(L"holdTime"), 0, 10000);
    s.growMs = std::clamp(Wh_GetIntSetting(L"growDuration"), 0, 5000);
    s.shrinkMs = std::clamp(Wh_GetIntSetting(L"shrinkDuration"), 0, 5000);
    s.disableInFullscreen = Wh_GetIntSetting(L"disableInFullscreen") != 0;
    return s;
}

////////////////////////////////////////////////////////////////////////////////
// System cursors

struct CursorType {
    DWORD id;               // OCR_* value used by SetSystemCursor.
    PCWSTR registryName;    // Value under HKCU\Control Panel\Cursors.
    bool animatedByDefault; // Built-in version is animated.
};

