};
struct RefreshQueue {
    uint32_t flags = 0;
    unsigned int passes = 0;
    void Request(uint32_t requested) {
        flags |= requested;
        passes = 3;
    }
    bool Pending() const { return flags != 0 || passes != 0; }
    uint32_t Take() {
        auto result = std::exchange(flags, 0);
        if (passes)
            --passes;
        return result;
    }
};
