void WINAPI ShowHook(void* self, POINT pt, int kind) {
    struct ShowingScope {
        void* previous;
        explicit ShowingScope(void* manager)
            : previous(std::exchange(showing, manager)) {}
        ~ShowingScope() { showing = previous; }
    } scope(self);
