using RegOpenKeyExW_t = decltype(&RegOpenKeyExW);
RegOpenKeyExW_t RegOpenKeyExW_Original;
LSTATUS WINAPI RegOpenKeyExW_Hook(HKEY hKey,
                                  LPCWSTR lpSubKey,
                                  DWORD ulOptions,
                                  REGSAM samDesired,
                                  PHKEY phkResult) {
    LSTATUS result = RegOpenKeyExW_Original(hKey, lpSubKey, ulOptions,
                                            samDesired, phkResult);
    if (result == ERROR_SUCCESS || !g_reportCompositionDiagAsDisabled ||
        hKey != HKEY_LOCAL_MACHINE || !lpSubKey ||
        _wcsicmp(lpSubKey, L"Software\\Microsoft\\XAML\\Debug") != 0) {
        return result;
    }

    // The key usually doesn't exist, and the value isn't queried unless the key
    // could be opened, so hand out a key which does exist.
    Wh_Log(L"Substituting the XAML debug key");
    return RegOpenKeyExW_Original(HKEY_LOCAL_MACHINE, L"Software\\Microsoft",
                                  ulOptions, samDesired, phkResult);
}

using RegQueryValueExW_t = decltype(&RegQueryValueExW);
RegQueryValueExW_t RegQueryValueExW_Original;
LSTATUS WINAPI RegQueryValueExW_Hook(HKEY hKey,
                                     LPCWSTR lpValueName,
                                     LPDWORD lpReserved,
                                     LPDWORD lpType,
                                     LPBYTE lpData,
                                     LPDWORD lpcbData) {
    if (!g_reportCompositionDiagAsDisabled || !lpValueName ||
        _wcsicmp(lpValueName, L"DisableCompositionDiag") != 0) {
        return RegQueryValueExW_Original(hKey, lpValueName, lpReserved, lpType,
                                         lpData, lpcbData);
    }

    Wh_Log(L"Reporting DisableCompositionDiag as set");

    if (lpType) {
        *lpType = REG_DWORD;
    }

    if (lpData && (!lpcbData || *lpcbData < sizeof(DWORD))) {
        if (lpcbData) {
            *lpcbData = sizeof(DWORD);
        }
        return ERROR_MORE_DATA;
    }

    if (lpData) {
        *reinterpret_cast<DWORD*>(lpData) = 1;
    }

    if (lpcbData) {
        *lpcbData = sizeof(DWORD);
    }

    return ERROR_SUCCESS;
}

HWND GetCoreWnd() {
    struct ENUM_WINDOWS_PARAM {
        HWND* hWnd;
    };

    HWND hWnd = nullptr;
    ENUM_WINDOWS_PARAM param = {&hWnd};
    EnumWindows(
        [](HWND hWnd, LPARAM lParam) -> BOOL {
            ENUM_WINDOWS_PARAM& param = *(ENUM_WINDOWS_PARAM*)lParam;

            WCHAR szClassName[32];
            if (GetClassName(hWnd, szClassName, ARRAYSIZE(szClassName)) == 0) {
                return TRUE;
            }

            auto isCurrentProcessWnd = [](HWND hWnd) {
                DWORD dwProcessId = 0;
                return GetWindowThreadProcessId(hWnd, &dwProcessId) &&
                       dwProcessId == GetCurrentProcessId();
            };

            // The CoreWindow is top-level until the frame window adopts it,
            // and while the app is minimized.
            if (_wcsicmp(szClassName, L"Windows.UI.Core.CoreWindow") == 0) {
                if (isCurrentProcessWnd(hWnd)) {
                    *param.hWnd = hWnd;
                    return FALSE;
                }

                return TRUE;
            }

            if (_wcsicmp(szClassName, L"ApplicationFrameWindow") != 0) {
                return TRUE;
            }

            // Look for a direct child CoreWindow belonging to this process.
            HWND hCoreWnd = nullptr;
            while ((hCoreWnd = FindWindowEx(hWnd, hCoreWnd,
                                            L"Windows.UI.Core.CoreWindow",
                                            nullptr)) != nullptr) {
                if (isCurrentProcessWnd(hCoreWnd)) {
                    *param.hWnd = hCoreWnd;
                    return FALSE;
                }
            }

            return TRUE;
        },
        (LPARAM)&param);

    return hWnd;
}

PTP_TIMER g_statsTimer;

bool StartStatsTimer() {
    static constexpr WCHAR kStatsBaseUrl[] =
        L"https://github.com/ramensoftware/"
        L"windows-11-settings-styling-guide/"
        L"releases/download/stats-v2/";

    ULONGLONG lastStatsTime = 0;
    Wh_GetBinaryValue(L"statsTimerLastTime", &lastStatsTime,
                      sizeof(lastStatsTime));

    // -1 can be set for disabling the stats timer.
    if (lastStatsTime == 0xFFFFFFFF'FFFFFFFF) {
        return false;
    }

    FILETIME currentTimeFt;
    GetSystemTimeAsFileTime(&currentTimeFt);

    ULONGLONG currentTime = ((ULONGLONG)currentTimeFt.dwHighDateTime << 32) |
                            currentTimeFt.dwLowDateTime;

    constexpr ULONGLONG k10Minutes = 10 * 60 * 10000000LL;
    constexpr ULONGLONG k24Hours = 24 * 60 * 60 * 10000000LL;
    constexpr ULONGLONG k10Seconds = 10 * 10000000LL;

    ULONGLONG minDueTime = currentTime + k10Seconds;
    ULONGLONG maxDueTime = currentTime + k24Hours;

    ULONGLONG dueTime = lastStatsTime + k24Hours;
    if (dueTime < minDueTime) {
        dueTime = minDueTime;
    } else if (dueTime > maxDueTime) {
        dueTime = maxDueTime;
    }

    g_statsTimer = CreateThreadpoolTimer(
        [](PTP_CALLBACK_INSTANCE, PVOID, PTP_TIMER) {
            Wh_Log(L">");

            string_setting_unique_ptr themeName(Wh_GetStringSetting(L"theme"));
            if (!*themeName.get()) {
                return;
            }

            HANDLE mutex =
                CreateMutex(nullptr, FALSE, L"WindhawkStats_" WH_MOD_ID);
            if (mutex) {
                WaitForSingleObject(mutex, INFINITE);
            }

            ULONGLONG lastStatsTime = 0;
            Wh_GetBinaryValue(L"statsTimerLastTime", &lastStatsTime,
                              sizeof(lastStatsTime));

            FILETIME currentTimeFt;
            GetSystemTimeAsFileTime(&currentTimeFt);
            ULONGLONG currentTime =
                ((ULONGLONG)currentTimeFt.dwHighDateTime << 32) |
                currentTimeFt.dwLowDateTime;

            const WH_URL_CONTENT* content = nullptr;
            if (currentTime - lastStatsTime >= k10Minutes) {
                Wh_SetBinaryValue(L"statsTimerLastTime", &currentTime,
                                  sizeof(currentTime));

                std::wstring themeNameEscaped = themeName.get();
                std::replace(themeNameEscaped.begin(), themeNameEscaped.end(),
                             L' ', L'_');
                std::replace(themeNameEscaped.begin(), themeNameEscaped.end(),
                             L'&', L'_');
                std::replace(themeNameEscaped.begin(), themeNameEscaped.end(),
                             L'.', L'_');

                std::wstring statsUrl = kStatsBaseUrl;
                statsUrl += themeNameEscaped;
                statsUrl += L".txt";

                Wh_Log(L"Submitting stats to %s", statsUrl.c_str());

                content = Wh_GetUrlContent(statsUrl.c_str(), nullptr);
            } else {
                Wh_Log(L"Skipping, last submission %llu seconds ago",
                       (currentTime - lastStatsTime) / 10000000LL);
            }

            if (mutex) {
                ReleaseMutex(mutex);
                CloseHandle(mutex);
            }

            if (!content) {
                Wh_Log(L"Failed to get stats content");
                return;
            }

            if (content->statusCode != 200) {
                Wh_Log(L"Stats content status code: %d", content->statusCode);
            }

            Wh_FreeUrlContent(content);
            Wh_Log(L"Stats content submitted");
        },
        nullptr, nullptr);
    if (!g_statsTimer) {
        Wh_Log(L"Failed to create stats timer");
        return false;
    }

    constexpr DWORD k24HoursInMs = 24 * 60 * 60 * 1000;
    constexpr DWORD k1SecondInMs = 1000;

    FILETIME dueTimeFt;
    dueTimeFt.dwLowDateTime = (DWORD)(dueTime & 0xFFFFFFFF);
    dueTimeFt.dwHighDateTime = (DWORD)(dueTime >> 32);
    SetThreadpoolTimer(g_statsTimer, &dueTimeFt, k24HoursInMs, k1SecondInMs);
    return true;
}

void StopStatsTimer() {
    if (g_statsTimer) {
        SetThreadpoolTimer(g_statsTimer, nullptr, 0, 0);
        WaitForThreadpoolTimerCallbacks(g_statsTimer, TRUE);
        CloseThreadpoolTimer(g_statsTimer);
        g_statsTimer = nullptr;
    }
}

BOOL Wh_ModInit() {
    Wh_Log(L">");

    HMODULE user32Module =
        LoadLibraryEx(L"user32.dll", nullptr, LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (user32Module) {
        void* pCreateWindowInBand =
            (void*)GetProcAddress(user32Module, "CreateWindowInBand");
        if (pCreateWindowInBand) {
            Wh_SetFunctionHook(pCreateWindowInBand,
                               (void*)CreateWindowInBand_Hook,
                               (void**)&CreateWindowInBand_Original);
        }

        void* pCreateWindowInBandEx =
            (void*)GetProcAddress(user32Module, "CreateWindowInBandEx");
        if (pCreateWindowInBandEx) {
            Wh_SetFunctionHook(pCreateWindowInBandEx,
                               (void*)CreateWindowInBandEx_Hook,
                               (void**)&CreateWindowInBandEx_Original);
        }
    }

    HMODULE kernelBaseModule = GetModuleHandle(L"kernelbase.dll");
    void* pKernelBaseRegOpenKeyExW =
        (void*)GetProcAddress(kernelBaseModule, "RegOpenKeyExW");
    Wh_SetFunctionHook(pKernelBaseRegOpenKeyExW, (void*)RegOpenKeyExW_Hook,
                       (void**)&RegOpenKeyExW_Original);

    void* pKernelBaseRegQueryValueExW =
        (void*)GetProcAddress(kernelBaseModule, "RegQueryValueExW");
    Wh_SetFunctionHook(pKernelBaseRegQueryValueExW,
                       (void*)RegQueryValueExW_Hook,
                       (void**)&RegQueryValueExW_Original);

    StartStatsTimer();

    return TRUE;
}

void Wh_ModAfterInit() {
    Wh_Log(L">");

    HWND hCoreWnd = GetCoreWnd();
    if (hCoreWnd) {
        Wh_Log(L"Initializing - Found core window");
        RunFromWindowThread(
            hCoreWnd, [](PVOID) { InitializeSettingsAndTap(); }, nullptr);
    }
}

void Wh_ModUninit() {
    Wh_Log(L">");

    StopStatsTimer();

    StopImageDownloads();

    // Before the UI threads are uninitialized, so that a retry can't be
    // scheduled on a thread which is being uninitialized.
    StopImageLoadRetries();

    if (auto watcher = ExchangeVisualTreeWatcher(nullptr)) {
        watcher->UnadviseVisualTreeChange();
    }

    HWND hCoreWnd = GetCoreWnd();
    if (hCoreWnd) {
        Wh_Log(L"Uninitializing - Found core window");
        RunFromWindowThread(
            hCoreWnd, [](PVOID) { UninitializeSettingsAndTap(); }, nullptr);
    }
}

void Wh_ModSettingsChanged() {
    Wh_Log(L">");

    if (auto watcher = ExchangeVisualTreeWatcher(nullptr)) {
        watcher->UnadviseVisualTreeChange();
    }

    HWND hCoreWnd = GetCoreWnd();
    if (hCoreWnd) {
        Wh_Log(L"Reinitializing - Found core window");
        RunFromWindowThread(
            hCoreWnd,
            [](PVOID) {
                UninitializeSettingsAndTap();
                InitializeSettingsAndTap();
            },
            nullptr);
    }
}

// ==WindhawkMod==
// @id              auto-open-on-hover
// @name            Auto-open on Hover
// @description     Automatically opens selected Windows taskbar flyouts when hovered.
// @version         0.1.0-dev.10
// @author          HHeitlager
// @github          https://github.com/hheitlager
// @include         explorer.exe
// @architecture    x86-64
// @compilerOptions -DWIN32_LEAN_AND_MEAN -lole32 -loleaut32 -lruntimeobject -lcomctl32
// @license         MIT
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
# Auto-open on Hover

Open selected Windows 11 taskbar controls after the pointer rests over them.

## Targets

- Start menu
- Hidden system tray icons
- Notification center

The taskbar controls are identified by their XAML names, AutomationIds,
accessible names or class names. Windows can change these between builds, so
each target accepts a semicolon-separated list of identifiers in Settings.

## Behavior

The mod waits for the configured hover delay, then sends one left-click at the
current pointer position to the matching taskbar control. Moving the pointer
away before the delay cancels the opening. Holding a mouse button also cancels
it, so dragging across the taskbar does not activate a flyout.

Flyouts opened by hover close after the pointer leaves both the taskbar target
and its popup for the configured closing delay. Clicking inside the popup keeps
it open, matching the hover-to-open interaction used by Simple System Resources.

Diagnostics are enabled by default and write `AOH:` trace lines to the Windhawk
log. They include the window under the pointer, popup candidate rectangles,
whether the pointer matched a popup by window handle or bounds, and close actions.
Some Windows shell flyouts reuse a `CoreWindow` that was already present before
opening; the mod identifies its host process and adopts it when the pointer
enters it shortly after hover activation. The hidden-icons tooltip can also be
suppressed with a setting when it covers the flyout.

For the hidden-icons flyout, enable **Hide hidden-icons tooltip** if Windows'
chevron tooltip covers part of the opened icons. It only hides matching XAML
tooltip windows owned by Explorer and positioned next to the chevron or over
the flyout.

A left-click is used because these taskbar controls do not expose one common
public XAML API for opening their flyouts. Since it follows each control's
normal click behavior, hovering a control whose flyout is already open can
close it. This version is intended for Windows 11 x64.

## License

MIT License.
*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
- General:
  - startMenuEnabled: true
    $name: Start menu
  - hiddenIconsEnabled: true
    $name: Hidden system tray icons
  - notificationCenterEnabled: true
    $name: Notification center
  - hoverDelay: 500
    $name: Hover delay (ms)
    $description: Wait this long before opening (100 to 3000 ms).
  - hoverCloseDelay: 300
    $name: Hover closing delay (ms)
    $description: Close a hover-opened popup after the pointer leaves both it and its taskbar target (100 to 3000 ms).
  - hideHiddenIconsTooltip: false
    $name: Hide hidden-icons tooltip
    $description: Hide the taskbar tooltip that can cover the hidden-icons flyout.
  $name: General
- Identifiers:
  - startMenuIdentifiers: "StartButton;StartMenuButton;Start"
    $name: Start menu
    $description: Semicolon-separated XAML names, class names or AutomationIds. Matching is case-insensitive.
  - hiddenIconsIdentifiers: "ShowHiddenIcons;SystemTrayChevron;ChevronIconView;OverflowButton"
    $name: Hidden system tray icons
    $description: Semicolon-separated XAML names, class names or AutomationIds.
  - notificationCenterIdentifiers: "NotificationCenterButton;NotificationIcon;NotificationCenter;Notifications;Show notifications;Calendar"
    $name: Notification center
    $description: Semicolon-separated XAML names, class names or AutomationIds.
  $name: Identifiers
- Diagnostics:
  - debugLogging: true
    $name: Debug logging
    $description: Log target, window-hit, popup-bounds and hover-state transitions to the Windhawk log.
  $name: Diagnostics
*/
// ==/WindhawkModSettings==

