using namespace winrt;
using namespace Windows::UI::Xaml;
using namespace Windows::UI::Xaml::Controls;
using namespace Windows::UI::Xaml::Input;
using namespace Windows::UI::Xaml::Media;
using namespace Windows::UI::Xaml::Hosting;

namespace input = Windows::UI::Xaml::Input;

// Taskbar host access follows the same Windhawk taskbar-host pattern used by
// the attached Simple System Resources source.
using HostGetter = void*(WINAPI*)(void*, void*);
using FrameHeight = int(WINAPI*)(void*);
using Decref = void(WINAPI*)(void*);
using StartTaskbar = void(WINAPI*)(void*);
HostGetter getHost = nullptr;
FrameHeight frameHeight = nullptr;
Decref decref = nullptr;
StartTaskbar startTaskbarOriginal = nullptr;
void* siteVtable = nullptr;

std::atomic<bool> stopping{false};
std::atomic<bool> debugLogging{true};
std::atomic<bool> hideHiddenIconsTooltip{false};
std::atomic<unsigned> hoverDelay{500};
std::atomic<unsigned> hoverCloseDelay{300};
std::atomic<bool> targetEnabled[3] = {true, true, true};
std::wstring targetNames[3] = {
    L"StartButton;StartMenuButton;Start",
    L"ShowHiddenIcons;SystemTrayChevron;ChevronIconView;OverflowButton",
    L"NotificationCenterButton;NotificationIcon;NotificationCenter;Notifications;Show notifications;Calendar"
};
std::recursive_mutex stateMutex;
std::atomic<ULONGLONG> suppressHoverUntil{0};

#define AOH_DEBUG(...) do { if (debugLogging.load()) Wh_Log(__VA_ARGS__); } while (0)

// Extracted and generalized hover-intent state from Simple System Resources.
enum class HoverAction { None, Open, Close };
struct HoverState {
    bool overTarget = false, overPopup = false, pending = false, hoverOpened = false;
    bool opening = false;
    uint64_t enteredAt = 0, outsideAt = 0, requestedAt = 0;

    void Enter(uint64_t now) {
        overTarget = true;
        outsideAt = 0;
        if (!hoverOpened) { pending = true; enteredAt = now; }
    }
    void Leave(uint64_t now) {
        overTarget = false;
        pending = false;
        if (!overPopup && !outsideAt) outsideAt = now;
    }
    void PopupPointer(bool inside, uint64_t now) {
        overPopup = inside;
        if (inside) outsideAt = 0;
        else if (!overTarget && !outsideAt) outsideAt = now;
    }
    void Presented(uint64_t now) {
        opening = false;
        if (hoverOpened && !overTarget && !overPopup) outsideAt = now;
    }
    void Pin() {
        pending = false;
        hoverOpened = false;
        opening = false;
        outsideAt = 0;
    }
    void Reset() { *this = {}; }
    HoverAction Tick(uint64_t now, unsigned openDelay, unsigned closeDelay) {
        if (pending && overTarget && now - enteredAt >= openDelay) {
            pending = false; hoverOpened = true; opening = true;
            requestedAt = now; outsideAt = 0;
            return HoverAction::Open;
        }
        if (hoverOpened && !opening && !overTarget && !overPopup && outsideAt &&
            now - outsideAt >= closeDelay) {
            Pin();
            return HoverAction::Close;
        }
        return HoverAction::None;
    }
};

enum class Target : unsigned { Start = 0, HiddenIcons = 1, NotificationCenter = 2 };
struct WindowSnapshot { HWND hwnd; bool visible; };
struct TargetState {
    HoverState hover;
    weak_ref<FrameworkElement> element;
    HWND popupWindow = nullptr;
    std::vector<WindowSnapshot> windowsBeforeOpen;
    std::vector<HWND> popupCandidates;
    HWND lastHitRoot = nullptr;
    bool lastOverPopup = false;
    bool openTimeoutLogged = false;
};
struct TaskbarState {
    HWND hwnd = nullptr;
    bool subclassed = false;
    bool timer = false;
    std::array<TargetState, 3> targets;
    std::array<bool, 3> boundTargets{};
};
std::unordered_map<HWND, TaskbarState> taskbars;

UINT HoverTimerId() {
    static UINT id = RegisterWindowMessageW(L"AutoOpenOnHoverTimer_" WH_MOD_ID);
    return id;
}

HWND PrimaryTaskbarWindow() {
    HWND hwnd = FindWindowW(L"Shell_TrayWnd", nullptr);
    DWORD pid = 0;
    if (hwnd) GetWindowThreadProcessId(hwnd, &pid);
    return pid == GetCurrentProcessId() ? hwnd : nullptr;
}

FrameworkElement TaskbarRoot(HWND hwnd) {
    if (hwnd != PrimaryTaskbarWindow()) return nullptr;
    HWND taskband = (HWND)GetPropW(hwnd, L"TaskbandHWND");
    if (!taskband) return nullptr;
    auto site = (void**)GetWindowLongPtrW(taskband, 0);
    if (!site) return nullptr;
    int index = 0;
    for (; index < 20 && *site != siteVtable; ++index) ++site;
    if (index == 20) return nullptr;

    auto code = reinterpret_cast<BYTE const*>(frameHeight);
    size_t offset = 0x10;
    if (code[0] == 0x48 && code[1] == 0x83 && code[2] == 0xEC &&
        code[4] == 0x48 && code[5] == 0x83 && code[6] == 0xC1 && code[7] <= 0x7F) {
        offset = code[7];
    }
    void* host[2]{};
    getHost(site, host);
    if (!host[1]) return nullptr;
    struct ReleaseHost {
        void* control;
        ~ReleaseHost() { decref(control); }
    } release{host[1]};
    if (!host[0]) return nullptr;
    auto unknown = *(IUnknown**)((BYTE*)host[0] + offset);
    if (!unknown) return nullptr;
    FrameworkElement element{nullptr};
    unknown->QueryInterface(guid_of<FrameworkElement>(), put_abi(element));
    auto root = element ? element.XamlRoot() : nullptr;
    return root ? root.Content().try_as<FrameworkElement>() : nullptr;
}

bool NameMatches(std::wstring const& candidate, std::wstring const& configured) {
    size_t start = 0;
    while (start <= configured.size()) {
        size_t end = configured.find(L';', start);
        if (end == std::wstring::npos) end = configured.size();
        std::wstring name = configured.substr(start, end - start);
        while (!name.empty() && iswspace(name.front())) name.erase(name.begin());
        while (!name.empty() && iswspace(name.back())) name.pop_back();
        if (!name.empty()) {
            auto it = std::search(candidate.begin(), candidate.end(), name.begin(), name.end(),
                [](wchar_t a, wchar_t b) { return towlower(a) == towlower(b); });
            if (it != candidate.end()) return true;
        }
        if (end == configured.size()) break;
        start = end + 1;
    }
    return false;
}

bool ElementMatches(FrameworkElement const& element, std::wstring const& configured) {
    if (NameMatches(std::wstring(element.Name()), configured)) return true;
    if (NameMatches(std::wstring(Automation::AutomationProperties::GetAutomationId(element)), configured)) return true;
    if (NameMatches(std::wstring(Automation::AutomationProperties::GetName(element)), configured)) return true;
    return NameMatches(std::wstring(get_class_name(element)), configured);
}

void EnsureTimer(HWND hwnd);
bool CursorOverElement(HWND hwnd, FrameworkElement const& element);
void OnTargetEntered(HWND hwnd, Target target, FrameworkElement const& element) {
    std::lock_guard<std::recursive_mutex> lock(stateMutex);
    if (stopping || !targetEnabled[unsigned(target)] ||
        GetTickCount64() < suppressHoverUntil.load()) return;
    if ((GetAsyncKeyState(VK_LBUTTON) & 0x8000) || (GetAsyncKeyState(VK_RBUTTON) & 0x8000)) return;
    auto found = taskbars.find(hwnd);
    if (found == taskbars.end()) return;
    auto& state = found->second.targets[unsigned(target)];
    AOH_DEBUG(L"AOH: enter target=%u hwnd=%p cursor-check pending=%d opened=%d",
              unsigned(target), hwnd, state.hover.pending, state.hover.hoverOpened);
    state.element = make_weak(element);
    state.hover.Enter(GetTickCount64());
    EnsureTimer(hwnd);
}

void OnTargetExited(HWND hwnd, Target target) {
    std::lock_guard<std::recursive_mutex> lock(stateMutex);
    auto found = taskbars.find(hwnd);
    if (found == taskbars.end()) return;
    auto element = found->second.targets[unsigned(target)].element.get();
    if (element && CursorOverElement(hwnd, element)) return;
    AOH_DEBUG(L"AOH: exit target=%u hwnd=%p opened=%d popup=%d",
              unsigned(target), hwnd,
              found->second.targets[unsigned(target)].hover.hoverOpened,
              found->second.targets[unsigned(target)].hover.overPopup);
    found->second.targets[unsigned(target)].hover.Leave(GetTickCount64());
}

bool NameMatches(std::wstring const& candidate, std::wstring const& configured);
bool GetElementScreenRect(HWND hwnd, FrameworkElement const& element, RECT& screenRect);

bool CursorOverElement(HWND hwnd, FrameworkElement const& element) {
    RECT bounds{};
    POINT cursor{};
    return GetElementScreenRect(hwnd, element, bounds) && GetCursorPos(&cursor) &&
           PtInRect(&bounds, cursor);
}

bool GetElementScreenRect(HWND hwnd, FrameworkElement const& element, RECT& screenRect) {
    if (!element || element.Visibility() != Visibility::Visible ||
        element.ActualWidth() <= 0 || element.ActualHeight() <= 0) return false;
    auto xamlRoot = element.XamlRoot();
    if (!xamlRoot) return false;
    auto root = xamlRoot.Content().try_as<UIElement>();
    if (!root) return false;
    auto bounds = element.TransformToVisual(root).TransformBounds(
        Windows::Foundation::Rect{0, 0, float(element.ActualWidth()), float(element.ActualHeight())});
    POINT origin{};
    if (!ClientToScreen(hwnd, &origin)) return false;
    double scale = xamlRoot.RasterizationScale();
    if (scale <= 0) return false;
    screenRect = RECT{
        origin.x + LONG(bounds.X * scale),
        origin.y + LONG(bounds.Y * scale),
        origin.x + LONG((bounds.X + bounds.Width) * scale),
        origin.y + LONG((bounds.Y + bounds.Height) * scale)};
    return screenRect.right > screenRect.left && screenRect.bottom > screenRect.top;
}

std::wstring WindowProcessImagePath(HWND hwnd) {
    DWORD pid = 0;
    GetWindowThreadProcessId(hwnd, &pid);
    if (!pid) return {};
    HANDLE process = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid);
    if (!process) return {};
    std::array<wchar_t, 1024> path{};
    DWORD length = static_cast<DWORD>(path.size());
    bool succeeded = QueryFullProcessImageNameW(process, 0, path.data(), &length) != FALSE;
    CloseHandle(process);
    return succeeded ? std::wstring(path.data(), length) : std::wstring{};
}

std::wstring ImageBaseName(std::wstring const& imagePath) {
    size_t separator = imagePath.find_last_of(L"\\/");
    return separator == std::wstring::npos ? imagePath : imagePath.substr(separator + 1);
}

bool EqualsIgnoreCase(std::wstring const& a, wchar_t const* b) {
    return CompareStringOrdinal(a.c_str(), -1, b, -1, TRUE) == CSTR_EQUAL;
}

bool IsKnownCoreWindowHost(unsigned target, std::wstring const& imageName) {
    if (target == 0) {
        return EqualsIgnoreCase(imageName, L"StartMenuExperienceHost.exe") ||
               EqualsIgnoreCase(imageName, L"ShellExperienceHost.exe");
    }
    if (target == 2) {
        return EqualsIgnoreCase(imageName, L"ShellExperienceHost.exe") ||
               EqualsIgnoreCase(imageName, L"ShellHost.exe");
    }
    return false;
}

bool IsSystemAppImage(std::wstring const& imagePath) {
    return NameMatches(imagePath, L"\\Windows\\SystemApps\\");
}

bool IsHiddenIconsTooltip(HWND taskbar, FrameworkElement const& element,
                          TargetState const& targetState) {
    if (!hideHiddenIconsTooltip.load() || !element) return false;
    RECT chevron{};
    if (!GetElementScreenRect(taskbar, element, chevron)) return false;

    DWORD taskbarPid = 0;
    GetWindowThreadProcessId(taskbar, &taskbarPid);
    RECT flyout{};
    bool hasFlyout = targetState.popupWindow &&
        IsWindowVisible(targetState.popupWindow) &&
        GetWindowRect(targetState.popupWindow, &flyout);

    HWND tooltip = nullptr;
    while ((tooltip = FindWindowExW(nullptr, tooltip, L"Xaml_WindowedPopupClass", nullptr))) {
        if (!IsWindowVisible(tooltip)) continue;
        DWORD pid = 0;
        GetWindowThreadProcessId(tooltip, &pid);
        if (taskbarPid && pid != taskbarPid) continue;

        RECT rect{};
        if (!GetWindowRect(tooltip, &rect)) continue;
        bool overlapsX = rect.left <= chevron.right && rect.right >= chevron.left;
        bool overlapsFlyout = hasFlyout && rect.left < flyout.right && rect.right > flyout.left &&
                              rect.top < flyout.bottom && rect.bottom > flyout.top;
        LONG band = chevron.bottom - chevron.top;
        LONG gapAbove = chevron.top - rect.bottom;
        LONG gapBelow = rect.top - chevron.bottom;
        bool besideChevron = (gapAbove >= 0 && gapAbove <= band) ||
                             (gapBelow >= 0 && gapBelow <= band);
        if (overlapsX && (overlapsFlyout || besideChevron)) {
            ShowWindowAsync(tooltip, SW_HIDE);
            AOH_DEBUG(L"AOH: hid hidden-icons tooltip hwnd=%p rect=%ld,%ld-%ld,%ld",
                      tooltip, rect.left, rect.top, rect.right, rect.bottom);
            return true;
        }
    }
    return false;
}

std::vector<WindowSnapshot> SnapshotWindows() {
    std::vector<WindowSnapshot> result;
    EnumWindows([](HWND hwnd, LPARAM param) -> BOOL {
        reinterpret_cast<std::vector<WindowSnapshot>*>(param)->push_back(
            {hwnd, IsWindowVisible(hwnd) != FALSE});
        return TRUE;
    }, reinterpret_cast<LPARAM>(&result));
    return result;
}

std::vector<HWND> FindNewPopupWindows(HWND taskbar,
                                     std::vector<WindowSnapshot> const& before) {
    struct SearchData {
        HWND taskbar;
        std::vector<WindowSnapshot> const* before;
        std::vector<HWND>* found;
        RECT monitor;
    } data{taskbar, &before, nullptr, {}};
    std::vector<HWND> result;
    data.found = &result;
    MONITORINFO monitorInfo{sizeof(monitorInfo)};
    if (GetMonitorInfoW(MonitorFromWindow(taskbar, MONITOR_DEFAULTTONEAREST), &monitorInfo))
        data.monitor = monitorInfo.rcMonitor;

    EnumWindows([](HWND hwnd, LPARAM param) -> BOOL {
        auto& data = *reinterpret_cast<SearchData*>(param);
        HWND root = GetAncestor(hwnd, GA_ROOT);
        if (!root || root == data.taskbar || root == PrimaryTaskbarWindow() || !IsWindowVisible(root))
            return TRUE;
        auto previous = std::find_if(data.before->begin(), data.before->end(),
            [root](WindowSnapshot const& entry) { return entry.hwnd == root; });
        if (previous != data.before->end() && previous->visible) return TRUE;

        RECT rect{};
        if (!GetWindowRect(root, &rect)) return TRUE;
        LONG width = rect.right - rect.left, height = rect.bottom - rect.top;
        if (width < 80 || height < 60 || width > data.monitor.right - data.monitor.left ||
            height > data.monitor.bottom - data.monitor.top) return TRUE;
        if (rect.right <= data.monitor.left || rect.left >= data.monitor.right ||
            rect.bottom <= data.monitor.top || rect.top >= data.monitor.bottom) return TRUE;
        LONG_PTR style = GetWindowLongPtrW(root, GWL_STYLE);
        wchar_t className[128]{};
        GetClassNameW(root, className, ARRAYSIZE(className));
        bool xamlPopup = NameMatches(className,
            L"CoreWindow;Xaml;Island;Popup;Overflow;ApplicationFrame");
        if (!(style & WS_POPUP) && !GetWindow(root, GW_OWNER) && !xamlPopup) return TRUE;
        if (std::find(data.found->begin(), data.found->end(), root) == data.found->end()) {
            data.found->push_back(root);
            DWORD pid = 0; GetWindowThreadProcessId(root, &pid);
            AOH_DEBUG(L"AOH: popup candidate hwnd=%p class='%s' pid=%lu rect=%ld,%ld-%ld,%ld style=0x%llX",
                      root, className, pid, rect.left, rect.top, rect.right, rect.bottom,
                      (unsigned long long)style);
        }
        return TRUE;
    }, reinterpret_cast<LPARAM>(&data));
    return result;
}

struct PopupHit {
    POINT cursor{};
    HWND hit = nullptr;
    HWND root = nullptr;
    HWND matched = nullptr;
    bool byBounds = false;
    bool coreWindowBoundsIgnored = false;
    bool overPopupMenu = false;
};
PopupHit TestPopupAtCursor(TargetState const& targetState) {
    PopupHit result{};
    if (!GetCursorPos(&result.cursor)) return result;
    result.hit = WindowFromPoint(result.cursor);
    result.root = result.hit ? GetAncestor(result.hit, GA_ROOT) : nullptr;
    if (result.root && IsWindowVisible(result.root)) {
        wchar_t hitClass[128]{};
        if (GetClassNameW(result.root, hitClass, ARRAYSIZE(hitClass)) &&
            wcscmp(hitClass, L"#32768") == 0) {
            result.overPopupMenu = true;
            return result;
        }
    }
    for (HWND candidate : targetState.popupCandidates) {
        if (result.root == candidate) {
            result.matched = candidate;
            return result;
        }
        wchar_t className[128]{};
        GetClassNameW(candidate, className, ARRAYSIZE(className));
        if (NameMatches(className, L"Windows.UI.Core.CoreWindow")) {
            // CoreWindow's GetWindowRect can cover much more than its visible
            // flyout surface. Trust hit-testing for this class, not its HWND rect.
            result.coreWindowBoundsIgnored = true;
            continue;
        }
        RECT rect{};
        if (IsWindowVisible(candidate) && GetWindowRect(candidate, &rect) &&
            result.cursor.x >= rect.left && result.cursor.x < rect.right &&
            result.cursor.y >= rect.top && result.cursor.y < rect.bottom) {
            result.matched = candidate;
            result.byBounds = true;
            return result;
        }
    }
    return result;
}

bool ClickElementCenter(FrameworkElement const& element) {
    if (!element || element.ActualWidth() <= 0 || element.ActualHeight() <= 0) return false;
    auto xamlRoot = element.XamlRoot();
    if (!xamlRoot) return false;
    auto root = xamlRoot.Content().try_as<UIElement>();
    if (!root) return false;
    auto center = element.TransformToVisual(root).TransformPoint(
        {float(element.ActualWidth() / 2), float(element.ActualHeight() / 2)});
    POINT origin{}, cursor{};
    if (!ClientToScreen(PrimaryTaskbarWindow(), &origin) || !GetCursorPos(&cursor)) return false;
    double scale = xamlRoot.RasterizationScale();
    POINT target{origin.x + LONG(center.X * scale), origin.y + LONG(center.Y * scale)};
    int left = GetSystemMetrics(SM_XVIRTUALSCREEN), top = GetSystemMetrics(SM_YVIRTUALSCREEN);
    int width = GetSystemMetrics(SM_CXVIRTUALSCREEN), height = GetSystemMetrics(SM_CYVIRTUALSCREEN);
    if (width <= 1 || height <= 1) return false;
    auto absolute = [&](POINT point) {
        return POINT{LONG((int64_t(point.x - left) * 65535) / (width - 1)),
                     LONG((int64_t(point.y - top) * 65535) / (height - 1))};
    };
    POINT destination = absolute(target), restore = absolute(cursor);
    INPUT events[4]{};
    events[0].type = INPUT_MOUSE;
    events[0].mi.dx = destination.x; events[0].mi.dy = destination.y;
    events[0].mi.dwFlags = MOUSEEVENTF_MOVE | MOUSEEVENTF_ABSOLUTE | MOUSEEVENTF_VIRTUALDESK;
    events[1].type = INPUT_MOUSE; events[1].mi.dwFlags = MOUSEEVENTF_LEFTDOWN;
    events[2].type = INPUT_MOUSE; events[2].mi.dwFlags = MOUSEEVENTF_LEFTUP;
    events[3].type = INPUT_MOUSE;
    events[3].mi.dx = restore.x; events[3].mi.dy = restore.y;
    events[3].mi.dwFlags = MOUSEEVENTF_MOVE | MOUSEEVENTF_ABSOLUTE | MOUSEEVENTF_VIRTUALDESK;
    suppressHoverUntil = GetTickCount64() + 250;
    bool sent = SendInput(ARRAYSIZE(events), events, sizeof(INPUT)) == ARRAYSIZE(events);
    AOH_DEBUG(L"AOH: taskbar toggle click hwnd=%p target=%ld,%ld restore=%ld,%ld sent=%d",
              PrimaryTaskbarWindow(), target.x, target.y, cursor.x, cursor.y, sent);
    return sent;
}

void DismissHoverPopup(TargetState& targetState, HWND taskbar) {
    if (auto element = targetState.element.get(); element && ClickElementCenter(element)) {
        AOH_DEBUG(L"AOH: dismiss by re-clicking target taskbar=%p popup=%p",
                  taskbar, targetState.popupWindow);
        return;
    }
    HWND popup = targetState.popupWindow;
    if (popup && IsWindowVisible(popup)) {
        AOH_DEBUG(L"AOH: dismiss by Escape popup=%p", popup);
        LPARAM keyDown = 1 | (LPARAM(MapVirtualKeyW(VK_ESCAPE, MAPVK_VK_TO_VSC)) << 16);
        LPARAM keyUp = keyDown | (LPARAM(1) << 30) | (LPARAM(1) << 31);
        PostMessageW(popup, WM_KEYDOWN, VK_ESCAPE, keyDown);
        PostMessageW(popup, WM_KEYUP, VK_ESCAPE, keyUp);
        return;
    }
    Wh_Log(L"Auto-open on Hover: couldn't dismiss hover-opened popup hwnd=%p", taskbar);
}

void ActivateTarget(FrameworkElement const& element) {
    // Use the control's normal pointer behavior. The cursor position is checked
    // immediately before this call, so the click lands on the hovered control.
    INPUT events[2]{};
    events[0].type = INPUT_MOUSE;
    events[0].mi.dwFlags = MOUSEEVENTF_LEFTDOWN;
    events[1].type = INPUT_MOUSE;
    events[1].mi.dwFlags = MOUSEEVENTF_LEFTUP;
    SendInput(ARRAYSIZE(events), events, sizeof(INPUT));
}

void TickTarget(HWND hwnd, unsigned index) {
    auto found = taskbars.find(hwnd);
    if (found == taskbars.end() || index >= found->second.targets.size()) return;
    auto& targetState = found->second.targets[index];
    auto element = targetState.element.get();
    if (!element) {
        targetState.hover.Reset();
        return;
    }
    if (!targetEnabled[index]) {
        targetState.hover.Reset();
        return;
    }
    uint64_t now = GetTickCount64();
    bool overTarget = CursorOverElement(hwnd, element);
    if (overTarget && !targetState.hover.overTarget) targetState.hover.Enter(now);
    else if (!overTarget && targetState.hover.overTarget) targetState.hover.Leave(now);

    if (targetState.hover.hoverOpened && targetState.popupCandidates.empty()) {
        targetState.popupCandidates = FindNewPopupWindows(hwnd, targetState.windowsBeforeOpen);
        if (!targetState.popupCandidates.empty())
            targetState.popupWindow = targetState.popupCandidates.front();
    }
    if (targetState.hover.hoverOpened && !targetState.hover.opening &&
        !targetState.popupCandidates.empty() &&
        std::none_of(targetState.popupCandidates.begin(), targetState.popupCandidates.end(),
                     [](HWND popup) { return IsWindowVisible(popup) != FALSE; })) {
        targetState.hover.Pin();
        targetState.popupWindow = nullptr;
        targetState.popupCandidates.clear();
        AOH_DEBUG(L"AOH: all tracked popup windows disappeared target=%u", index);
        return;
    }
    if (index == unsigned(Target::HiddenIcons) &&
        (overTarget || targetState.hover.hoverOpened)) {
        IsHiddenIconsTooltip(hwnd, element, targetState);
    }
    PopupHit popupHit = TestPopupAtCursor(targetState);
    if (targetState.hover.hoverOpened && !popupHit.matched && popupHit.root &&
        popupHit.root != hwnd && popupHit.root != PrimaryTaskbarWindow()) {
        auto previous = std::find_if(targetState.windowsBeforeOpen.begin(),
            targetState.windowsBeforeOpen.end(), [root = popupHit.root](WindowSnapshot const& entry) {
                return entry.hwnd == root;
            });
        wchar_t className[128]{};
        GetClassNameW(popupHit.root, className, ARRAYSIZE(className));
        bool newlyVisible = previous == targetState.windowsBeforeOpen.end() || !previous->visible;
        bool recentlyOpenedCoreWindow = targetState.popupCandidates.empty() &&
            NameMatches(className, L"Windows.UI.Core.CoreWindow") &&
            now - targetState.hover.requestedAt <= 5000;
        std::wstring imagePath = recentlyOpenedCoreWindow
            ? WindowProcessImagePath(popupHit.root) : std::wstring{};
        std::wstring imageName = ImageBaseName(imagePath);
        bool knownShellHost = recentlyOpenedCoreWindow &&
            IsKnownCoreWindowHost(index, imageName);
        bool systemAppFallback = recentlyOpenedCoreWindow && !knownShellHost &&
            IsSystemAppImage(imagePath);
        if (newlyVisible || knownShellHost || systemAppFallback) {
            targetState.popupCandidates.push_back(popupHit.root);
            targetState.popupWindow = popupHit.root;
            popupHit.matched = popupHit.root;
            DWORD pid = 0;
            GetWindowThreadProcessId(popupHit.root, &pid);
            wchar_t const* reason = newlyVisible ? L"newly-visible" :
                (knownShellHost ? L"known-shell-host" : L"system-app-fallback");
            AOH_DEBUG(L"AOH: registered pointer window as popup target=%u hwnd=%p class='%s' pid=%lu image='%s' point=%ld,%ld reason=%s elapsed=%llu ms",
                      index, popupHit.root, className, pid, imageName.c_str(),
                      popupHit.cursor.x, popupHit.cursor.y,
                      reason,
                      now - targetState.hover.requestedAt);
        } else if (recentlyOpenedCoreWindow) {
            DWORD pid = 0;
            GetWindowThreadProcessId(popupHit.root, &pid);
            AOH_DEBUG(L"AOH: rejected CoreWindow candidate target=%u hwnd=%p pid=%lu image='%s' systemApp=%d elapsed=%llu ms",
                      index, popupHit.root, pid, imageName.c_str(),
                      IsSystemAppImage(imagePath), now - targetState.hover.requestedAt);
        }
    }
    bool overPopup = popupHit.matched != nullptr || popupHit.overPopupMenu;
    if ((targetState.hover.pending || targetState.hover.hoverOpened) &&
        targetState.lastHitRoot != popupHit.root) {
        wchar_t className[128]{};
        DWORD pid = 0;
        if (popupHit.root) {
            GetClassNameW(popupHit.root, className, ARRAYSIZE(className));
            GetWindowThreadProcessId(popupHit.root, &pid);
        }
        AOH_DEBUG(L"AOH: pointer hit target=%u point=%ld,%ld hit=%p root=%p class='%s' pid=%lu candidates=%u matched=%p byBounds=%d coreWindowBoundsIgnored=%d popupMenu=%d",
                  index, popupHit.cursor.x, popupHit.cursor.y, popupHit.hit,
                  popupHit.root, className, pid,
                  unsigned(targetState.popupCandidates.size()), popupHit.matched,
                  popupHit.byBounds, popupHit.coreWindowBoundsIgnored,
                  popupHit.overPopupMenu);
        targetState.lastHitRoot = popupHit.root;
    }
    if (targetState.hover.overPopup != overPopup &&
        (targetState.hover.pending || targetState.hover.hoverOpened)) {
        AOH_DEBUG(L"AOH: popup-hover target=%u value=%d point=%ld,%ld root=%p matched=%p byBounds=%d popupMenu=%d",
                  index, overPopup, popupHit.cursor.x, popupHit.cursor.y,
                  popupHit.root, popupHit.matched, popupHit.byBounds,
                  popupHit.overPopupMenu);
    }
    targetState.lastOverPopup = overPopup;
    targetState.hover.PopupPointer(overPopup, now);
    if (targetState.hover.opening) {
        if (!targetState.popupCandidates.empty()) {
            targetState.hover.Presented(now);
        } else if (now - targetState.hover.requestedAt >= 1000) {
            targetState.hover.Presented(now);
            if (!targetState.openTimeoutLogged) {
                AOH_DEBUG(L"AOH: popup discovery still pending target=%u after 1000 ms; waiting for shell window",
                          index);
                targetState.openTimeoutLogged = true;
            }
        }
    }

    // A deliberate press inside the popup adopts it and disables hover-close.
    SHORT mouseState = GetAsyncKeyState(VK_LBUTTON) |
                       GetAsyncKeyState(VK_RBUTTON) |
                       GetAsyncKeyState(VK_MBUTTON);
    bool pressed = (mouseState & 0x8000) != 0;
    bool pressedSinceTick = (mouseState & 0x0001) != 0;
    if (pressed || pressedSinceTick) {
        targetState.hover.pending = false;
        if (targetState.hover.overPopup) {
            AOH_DEBUG(L"AOH: popup pinned by mouse input target=%u pressed=%d pressedSinceTick=%d",
                      index, pressed, pressedSinceTick);
            targetState.hover.Pin();
        }
        if (pressed) return;
    }

    auto action = targetState.hover.Tick(now, hoverDelay.load(), hoverCloseDelay.load());
    if (action == HoverAction::Open) {
        AOH_DEBUG(L"AOH: hover-open target=%u delay=%u ms", index, hoverDelay.load());
        for (unsigned otherIndex = 0; otherIndex < found->second.targets.size(); ++otherIndex) {
            if (otherIndex == index) continue;
            auto& other = found->second.targets[otherIndex];
            if (!other.hover.hoverOpened) continue;
            AOH_DEBUG(L"AOH: closing previous hover target=%u before opening target=%u",
                      otherIndex, index);
            DismissHoverPopup(other, hwnd);
            other.hover.Pin();
            other.popupWindow = nullptr;
            other.popupCandidates.clear();
        }
        targetState.popupWindow = nullptr;
        targetState.popupCandidates.clear();
        targetState.windowsBeforeOpen = SnapshotWindows();
        targetState.lastHitRoot = nullptr;
        targetState.lastOverPopup = false;
        targetState.openTimeoutLogged = false;
        ActivateTarget(element);
    } else if (action == HoverAction::Close) {
        AOH_DEBUG(L"AOH: hover-close target=%u delay=%u ms popup=%p candidates=%u",
                  index, hoverCloseDelay.load(), targetState.popupWindow,
                  unsigned(targetState.popupCandidates.size()));
        DismissHoverPopup(targetState, hwnd);
        targetState.popupWindow = nullptr;
    }
}

LRESULT CALLBACK TaskbarSubclass(HWND hwnd, UINT message, WPARAM wp, LPARAM lp,
                                  UINT_PTR id, DWORD_PTR data);

void StopTimer(HWND hwnd, bool detach) {
    auto found = taskbars.find(hwnd);
    if (found == taskbars.end()) return;
    auto& state = found->second;
    if (state.timer) KillTimer(hwnd, HoverTimerId());
    state.timer = false;
    if (detach && state.subclassed) {
        RemoveWindowSubclass(hwnd, TaskbarSubclass, HoverTimerId());
        state.subclassed = false;
    }
}

LRESULT CALLBACK TaskbarSubclass(HWND hwnd, UINT message, WPARAM wp, LPARAM lp, UINT_PTR id, DWORD_PTR data) {
    if (message == WM_NCDESTROY) {
        std::lock_guard<std::recursive_mutex> lock(stateMutex);
        StopTimer(hwnd, false);
        taskbars.erase(hwnd);
    } else if (message == WM_TIMER && wp == id && lp == 0) {
        std::lock_guard<std::recursive_mutex> lock(stateMutex);
        if (stopping) {
            KillTimer(hwnd, id);
            return 0;
        }
        for (unsigned i = 0; i < 3; ++i) TickTarget(hwnd, i);
        bool active = false;
        if (auto found = taskbars.find(hwnd); found != taskbars.end()) {
            for (auto const& target : found->second.targets)
                active |= target.hover.pending || target.hover.hoverOpened;
            if (!active) {
                KillTimer(hwnd, id);
                found->second.timer = false;
            }
        }
        return 0;
    }
    return DefSubclassProc(hwnd, message, wp, lp);
}

void EnsureTimer(HWND hwnd) {
    auto found = taskbars.find(hwnd);
    if (found == taskbars.end()) return;
    UINT id = HoverTimerId();
    if (!id) return;
    if (!found->second.subclassed) {
        if (!SetWindowSubclass(hwnd, TaskbarSubclass, id, 0)) {
            Wh_Log(L"Auto-open on Hover: taskbar subclass failed (%lu)", GetLastError());
            return;
        }
        found->second.subclassed = true;
    }
    if (!found->second.timer) {
        found->second.timer = SetTimer(hwnd, id, 40, nullptr) != 0;
        if (!found->second.timer) Wh_Log(L"Auto-open on Hover: timer failed (%lu)", GetLastError());
    }
}

void SaveToken(FrameworkElement const& element, wchar_t const* key, event_token token) {
    element.Resources().Insert(box_value(key), box_value(token.value));
}
bool LoadToken(FrameworkElement const& element, wchar_t const* key, event_token& token) {
    auto boxed = box_value(key);
    if (!element.Resources().HasKey(boxed)) return false;
    token.value = unbox_value<int64_t>(element.Resources().Lookup(boxed));
    element.Resources().Remove(boxed);
    return true;
}

void AttachTarget(FrameworkElement const& element, HWND hwnd, Target target) {
    wchar_t const* enteredKey = L"AutoOpenHoverEntered";
    wchar_t const* exitedKey = L"AutoOpenHoverExited";
    auto key = box_value(enteredKey);
    if (element.Resources().HasKey(key)) return;
    auto entered = element.PointerEntered([hwnd, target](
            winrt::Windows::Foundation::IInspectable const& sender,
            PointerRoutedEventArgs const&) {
        try { OnTargetEntered(hwnd, target, sender.as<FrameworkElement>()); }
        catch (hresult_error const& e) { Wh_Log(L"Auto-open on Hover: enter failed 0x%08X", unsigned(e.code().value)); }
    });
    auto exited = element.PointerExited([hwnd, target](
            winrt::Windows::Foundation::IInspectable const&,
            PointerRoutedEventArgs const&) {
        OnTargetExited(hwnd, target);
    });
    SaveToken(element, enteredKey, entered);
    SaveToken(element, exitedKey, exited);
}

void DetachTree(DependencyObject const& node) {
    if (!node) return;
    if (auto element = node.try_as<FrameworkElement>()) {
        event_token token{};
        if (LoadToken(element, L"AutoOpenHoverEntered", token)) element.PointerEntered(token);
        if (LoadToken(element, L"AutoOpenHoverExited", token)) element.PointerExited(token);
    }
    for (int i = 0; i < VisualTreeHelper::GetChildrenCount(node); ++i)
        DetachTree(VisualTreeHelper::GetChild(node, i));
}

void FindAndAttachTargets(DependencyObject const& node, HWND hwnd, int depth = 0) {
    if (!node || depth > 28) return;
    if (auto element = node.try_as<FrameworkElement>()) {
        std::wstring name(element.Name());
        std::wstring automationId(Automation::AutomationProperties::GetAutomationId(element));
        std::wstring automationName(Automation::AutomationProperties::GetName(element));
        std::wstring className(get_class_name(element));
        for (unsigned i = 0; i < 3; ++i) {
            if (targetEnabled[i] && ElementMatches(element, targetNames[i])) {
                AttachTarget(element, hwnd, Target(i));
                taskbars[hwnd].boundTargets[i] = true;
                Wh_Log(L"Auto-open on Hover: target %u bound: name='%s' id='%s' class='%s'",
                       i, name.c_str(), automationId.c_str(), className.c_str());
                break;
            }
        }
        auto contains = [](std::wstring const& value, wchar_t const* word) {
            return NameMatches(value, word);
        };
        if (contains(name, L"start") || contains(name, L"chevron") || contains(name, L"hidden") ||
            contains(name, L"notif") || contains(name, L"clock") ||
            contains(automationId, L"start") || contains(automationId, L"chevron") ||
            contains(automationId, L"hidden") || contains(automationId, L"notif") ||
            contains(automationName, L"start") || contains(automationName, L"chevron") ||
            contains(automationName, L"hidden") || contains(automationName, L"notif") ||
            contains(className, L"start") || contains(className, L"chevron") ||
            contains(className, L"hidden") || contains(className, L"notif")) {
            Wh_Log(L"Auto-open on Hover: candidate name='%s' id='%s' label='%s' class='%s'",
                   name.c_str(), automationId.c_str(), automationName.c_str(), className.c_str());
        }
    }
    for (int i = 0; i < VisualTreeHelper::GetChildrenCount(node); ++i)
        FindAndAttachTargets(VisualTreeHelper::GetChild(node, i), hwnd, depth + 1);
}

void ApplyTaskbar(HWND hwnd, bool remove) {
    std::lock_guard<std::recursive_mutex> lock(stateMutex);
    auto root = TaskbarRoot(hwnd);
    if (remove) {
        StopTimer(hwnd, true);
        if (root) DetachTree(root);
        taskbars.erase(hwnd);
        return;
    }
    if (!root) {
        Wh_Log(L"Auto-open on Hover: taskbar XAML root was not available hwnd=%p", hwnd);
        return;
    }
    auto& state = taskbars[hwnd];
    state.hwnd = hwnd;
    state.boundTargets = {};
    FindAndAttachTargets(root, hwnd);
    for (unsigned i = 0; i < 3; ++i) {
        if (targetEnabled[i] && !state.boundTargets[i])
            Wh_Log(L"Auto-open on Hover: no XAML target matched target %u; inspect candidate log lines and configure its identifier", i);
    }
}

struct UiRequest { HWND hwnd; bool remove; bool completed = false; };
bool ApplyTaskbarOnOwnerThread(HWND hwnd, bool remove) {
    if (!hwnd) return false;
    DWORD thread = GetWindowThreadProcessId(hwnd, nullptr);
    if (thread == GetCurrentThreadId()) {
        ApplyTaskbar(hwnd, remove);
        return true;
    }
    static UINT message = RegisterWindowMessageW(L"AutoOpenOnHoverDispatch_" WH_MOD_ID);
    if (!message) return false;
    HHOOK hook = SetWindowsHookExW(WH_CALLWNDPROC,
        [](int code, WPARAM wp, LPARAM lp) -> LRESULT {
            if (code == HC_ACTION) {
                auto const& event = *reinterpret_cast<CWPSTRUCT const*>(lp);
                if (event.message == RegisterWindowMessageW(L"AutoOpenOnHoverDispatch_" WH_MOD_ID)) {
                    auto& request = *reinterpret_cast<UiRequest*>(event.lParam);
                    try {
                        ApplyTaskbar(request.hwnd, request.remove);
                        request.completed = true;
                    } catch (hresult_error const& e) {
                        Wh_Log(L"Auto-open on Hover: UI dispatch failed 0x%08X", unsigned(e.code().value));
                    } catch (...) { Wh_Log(L"Auto-open on Hover: UI dispatch failed"); }
                }
            }
            return CallNextHookEx(nullptr, code, wp, lp);
        }, nullptr, thread);
    if (!hook) {
        Wh_Log(L"Auto-open on Hover: UI hook failed (%lu)", GetLastError());
        return false;
    }
    UiRequest request{hwnd, remove};
    SendMessageW(hwnd, message, 0, reinterpret_cast<LPARAM>(&request));
    UnhookWindowsHookEx(hook);
    return request.completed;
}

void WINAPI StartTaskbarHook(void* self) {
    startTaskbarOriginal(self);
    if (!stopping) {
        try {
            if (auto hwnd = PrimaryTaskbarWindow()) ApplyTaskbar(hwnd, false);
        } catch (...) { Wh_Log(L"Auto-open on Hover: taskbar attach failed"); }
    }
}

void LoadSettings() {
    debugLogging = Wh_GetIntSetting(L"Diagnostics.debugLogging") != 0;
    hideHiddenIconsTooltip = Wh_GetIntSetting(L"General.hideHiddenIconsTooltip") != 0;
    hoverDelay = std::clamp(Wh_GetIntSetting(L"General.hoverDelay"), 100, 3000);
    hoverCloseDelay = std::clamp(Wh_GetIntSetting(L"General.hoverCloseDelay"), 100, 3000);
    targetEnabled[0] = Wh_GetIntSetting(L"General.startMenuEnabled") != 0;
    targetEnabled[1] = Wh_GetIntSetting(L"General.hiddenIconsEnabled") != 0;
    targetEnabled[2] = Wh_GetIntSetting(L"General.notificationCenterEnabled") != 0;
    auto readNames = [](wchar_t const* setting, std::wstring& output) {
        auto value = Wh_GetStringSetting(setting);
        if (value) { output = value; Wh_FreeStringSetting(value); }
    };
    readNames(L"Identifiers.startMenuIdentifiers", targetNames[0]);
    readNames(L"Identifiers.hiddenIconsIdentifiers", targetNames[1]);
    readNames(L"Identifiers.notificationCenterIdentifiers", targetNames[2]);
}

BOOL Wh_ModInit() {
    LoadSettings();
    HMODULE taskbar = LoadLibraryExW(L"taskbar.dll", nullptr, LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!taskbar) return FALSE;
    WindhawkUtils::SYMBOL_HOOK hooks[] = {
        {{LR"(const CTaskBand::`vftable'{for `ITaskListWndSite'})"}, &siteVtable},
        {{LR"(public: virtual class std::shared_ptr<class TaskbarHost> __cdecl CTaskBand::GetTaskbarHost(void)const )"}, &getHost},
        {{LR"(public: int __cdecl TaskbarHost::FrameHeight(void)const )"}, &frameHeight},
        {{LR"(public: void __cdecl std::_Ref_count_base::_Decref(void))"}, &decref},
        {{LR"(public: virtual void __cdecl TrayUI::StartTaskbar(void))"}, &startTaskbarOriginal, StartTaskbarHook},
    };
    bool ok = WindhawkUtils::HookSymbols(taskbar, hooks, ARRAYSIZE(hooks));
    FreeLibrary(taskbar);
    if (!ok) Wh_Log(L"Auto-open on Hover: required taskbar symbols were not found; mod cannot attach");
    return ok ? TRUE : FALSE;
}

void Wh_ModAfterInit() {
    if (auto hwnd = PrimaryTaskbarWindow()) ApplyTaskbarOnOwnerThread(hwnd, false);
}

BOOL Wh_ModSettingsChanged(BOOL* reload) {
    *reload = FALSE;
    LoadSettings();
    if (auto hwnd = PrimaryTaskbarWindow()) ApplyTaskbarOnOwnerThread(hwnd, false);
    return TRUE;
}

void Wh_ModBeforeUninit() {
    stopping = true;
    if (auto hwnd = PrimaryTaskbarWindow()) ApplyTaskbarOnOwnerThread(hwnd, true);
}

void Wh_ModUninit() {}

