// After-icons is visually anchored to the last realized taskbar button.
// Never resize or re-column the taskbar's full-width ItemsRepeater.
static int g_afterIconsDiagnosticCount=0;
static void UpdateAfterIconsOnUiThread() {
    if(g_position!=L"after-icons" || !g_pill) return;
    auto root=LiveTaskbarRoot();
    auto grid=root.try_as<Grid>();
    if(!grid || grid.ActualWidth()<=0) return;
    Panel iconsParent{nullptr}; FrameworkElement repeater{nullptr};
    if(!FindApplicationRepeater(root,iconsParent,repeater) || !repeater) return;
    try {
        auto origin=repeater.TransformToVisual(grid).TransformPoint({0,0});
        double appRight=origin.X;
        unsigned measured=0;
        int count=VisualTreeHelper::GetChildrenCount(repeater);
        for(int i=0;i<count;++i) {
            auto child=VisualTreeHelper::GetChild(repeater,i).try_as<FrameworkElement>();
            if(!child || child.Visibility()!=Visibility::Visible ||
               child.ActualWidth()<=0 || child.ActualWidth()>400.0) continue;
            auto pos=child.TransformToVisual(grid).TransformPoint({0,0});
            if(std::isfinite(pos.X) && pos.X>=0 &&
               pos.X+child.ActualWidth()<=grid.ActualWidth()+1.0) {
                appRight=std::max(appRight,pos.X+child.ActualWidth());
                ++measured;
            }
        }
        double pillWidth=g_pill.ActualWidth();
        if(!std::isfinite(pillWidth) || pillWidth<=0) {
            g_pill.Measure({10000.0,100.0});
            pillWidth=g_pill.DesiredSize().Width;
        }
        if(!std::isfinite(pillWidth) || pillWidth<=0) {
            g_pill.Visibility(Visibility::Collapsed);
            return;
        }
        double centeredLeft=(grid.ActualWidth()-pillWidth)/2.0;
        double desiredLeft=appRight+(double)g_settings.nativeGap +
                           (double)(g_settings.placementMarginLeft-g_settings.placementMarginRight+g_settings.nativeMarginLeft-g_settings.nativeMarginRight);
        double rightLimit=grid.ActualWidth();
        if(auto tray=LiveTray()) {
            auto trayPos=tray.TransformToVisual(grid).TransformPoint({0,0});
            rightLimit=trayPos.X;
        }
        bool room=measured>0 && desiredLeft>=0 && desiredLeft+pillWidth<=rightLimit;
        g_pill.Visibility((room && g_contentAllowsVisibility)?Visibility::Visible:Visibility::Collapsed);
        if(room) {
            auto transform=g_pill.RenderTransform().try_as<TranslateTransform>();
            if(!transform) {transform=TranslateTransform();g_pill.RenderTransform(transform);}
            transform.X(desiredLeft-centeredLeft);
        }
        if(g_afterIconsDiagnosticCount<15) {
            EMBER_LOG_DEBUG(L"After-icons: repeaterW=%.1f measured=%u appRight=%.1f desired=%.1f trayLeft=%.1f pillW=%.1f room=%d",
                   repeater.ActualWidth(),measured,appRight,desiredLeft,rightLimit,pillWidth,room?1:0);
            ++g_afterIconsDiagnosticCount;
        }
    } catch(...) {
        EMBER_LOG_ERROR(L"After-icons measurement unavailable; retrying");
    }
}



// v1.6.0-dev.1: opt-in single-hop desktop navigation on Windows 11 24H2+.
// This undocumented interface is deliberately limited to the known 26100+
// ABI. On failure, retain the proven keyboard-based fallback.
static bool TrySwitchDesktopDirect(int target) {
 if(g_explorerBuildNumber < 26100) return false;
 static const GUID sidManager = {0xc5e0cdca,0x7b6e,0x41b2,{0x9f,0xc4,0xd9,0x39,0x75,0xcc,0x46,0x7b}};
 static const GUID iidManager = {0x53f5ca0b,0x158f,0x4124,{0x90,0x0c,0x05,0x71,0x58,0x06,0x0b,0x27}};
 static const GUID iidDesktop = {0x3f07f4be,0xb107,0x441a,{0xaf,0x0f,0x39,0xd8,0x25,0x29,0x07,0x2c}};
 IServiceProvider* provider=nullptr;
 HRESULT hr=CoCreateInstance(CLSID_ImmersiveShell,nullptr,
  CLSCTX_INPROC_SERVER|CLSCTX_LOCAL_SERVER,IID_PPV_ARGS(&provider));
 if(FAILED(hr)||!provider) {
  EMBER_LOG_ERROR(L"Direct navigation: shell provider unavailable hr=0x%08X",hr);
  return false;
 }
 IUnknown* manager=nullptr;
 hr=provider->QueryService(sidManager,iidManager,reinterpret_cast<void**>(&manager));
 provider->Release();
 if(FAILED(hr)||!manager) {
  EMBER_LOG_ERROR(L"Direct navigation: internal manager unavailable hr=0x%08X",hr);
  return false;
 }
 // IUnknown vtable: GetDesktops at slot 7; SwitchDesktopWithAnimation
 // at slot 21 for the Windows 11 24H2+ manager interface.
 void** methods=*reinterpret_cast<void***>(manager);
 using GetDesktopsFn=HRESULT(STDMETHODCALLTYPE*)(void*,IUnknown**);
 auto getDesktops=reinterpret_cast<GetDesktopsFn>(methods[7]);
 IUnknown* desktops=nullptr;
 hr=getDesktops(manager,&desktops);
 if(FAILED(hr)||!desktops) {
  EMBER_LOG_ERROR(L"Direct navigation: GetDesktops failed hr=0x%08X",hr);
  manager->Release();
  return false;
 }
 void** arrayMethods=*reinterpret_cast<void***>(desktops);
 using GetCountFn=HRESULT(STDMETHODCALLTYPE*)(void*,UINT*);
 using GetAtFn=HRESULT(STDMETHODCALLTYPE*)(void*,UINT,REFIID,void**);
 UINT count=0;
 hr=reinterpret_cast<GetCountFn>(arrayMethods[3])(desktops,&count);
 IUnknown* desktop=nullptr;
 if(SUCCEEDED(hr)&&target>=1&&static_cast<UINT>(target)<=count)
  hr=reinterpret_cast<GetAtFn>(arrayMethods[4])(desktops,
   static_cast<UINT>(target-1),iidDesktop,reinterpret_cast<void**>(&desktop));
 else hr=E_INVALIDARG;
 desktops->Release();
 if(FAILED(hr)||!desktop) {
  EMBER_LOG_ERROR(L"Direct navigation: target lookup failed hr=0x%08X",hr);
  manager->Release();
  return false;
 }
 using SwitchAnimatedFn=HRESULT(STDMETHODCALLTYPE*)(void*,void*);
 hr=reinterpret_cast<SwitchAnimatedFn>(methods[21])(manager,desktop);
 desktop->Release();
 manager->Release();
 EMBER_LOG_DEBUG(L"Direct animated switch to desktop %d: hr=0x%08X",target,hr);
 return SUCCEEDED(hr);
}

// Keyboard navigation fallback from v1.5.0, unchanged.
static void SwitchToDesktopFromMarker(int target) {
 // Always resolve the keyboard fallback against a fresh desktop ordering.
 auto state=ReadDesktopStateSnapshot();
 if(!state.valid) return;
 int current=state.currentDesktop;
 int count=state.desktopCount;
 if(target<1 || target>count || current<1 || current>count || target==current) return;
 if(Wh_GetIntSetting(L"Transitions.directMarkerNavigation") &&
    TrySwitchDesktopDirect(target)) return;
 const WORD arrow=target>current?VK_RIGHT:VK_LEFT;
 const int steps=std::abs(target-current);
 EMBER_LOG_DEBUG(L"Marker click fallback: current=%d target=%d steps=%d",current,target,steps);
 for(int i=0;i<steps && !g_unloading.load();++i) {
  INPUT keys[6]{};
  WORD codes[6]={VK_LWIN,VK_CONTROL,arrow,arrow,VK_CONTROL,VK_LWIN};
  for(int k=0;k<6;++k) {
   keys[k].type=INPUT_KEYBOARD;
   keys[k].ki.wVk=codes[k];
   if(k>=3) keys[k].ki.dwFlags=KEYEVENTF_KEYUP;
  }
  if(SendInput(6,keys,sizeof(INPUT))!=6) {
   EMBER_LOG_ERROR(L"Marker navigation: SendInput failed (%lu)",GetLastError());
   break;
  }
  if(i+1<steps) Sleep(100);
 }
}

// dev.20: independent hit-testable controls for marker navigation.
// Theme resolution is isolated from placement and desktop navigation.
struct MarkerPalette {
 winrt::Windows::UI::Color active, inactive, hover;
};
static winrt::Windows::UI::Color ThemeRgb(unsigned int rgb) {
 return winrt::Windows::UI::Color{255, static_cast<BYTE>((rgb>>16)&255),
  static_cast<BYTE>((rgb>>8)&255), static_cast<BYTE>(rgb&255)};
}
static bool ThemeLightMode() {
 DWORD value=0, size=sizeof(value);
 if(RegGetValueW(HKEY_CURRENT_USER,
   L"Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize",
   L"SystemUsesLightTheme",RRF_RT_REG_DWORD,nullptr,&value,&size)==ERROR_SUCCESS)
  return value!=0;
 return false;
}
static winrt::Windows::UI::Color ThemeWindowsAccent() {
 // DWM's colorization color follows the configured system accent on supported builds.
 using GetAccent=HRESULT (WINAPI*)(DWORD*,BOOL*);
 auto dll=GetModuleHandleW(L"dwmapi.dll");
 bool unload=false;
 if(!dll) {dll=LoadLibraryW(L"dwmapi.dll");unload=dll!=nullptr;}
 DWORD argb=0;BOOL opaque=FALSE;
 auto proc=dll?reinterpret_cast<GetAccent>(GetProcAddress(dll,"DwmGetColorizationColor")):nullptr;
 bool ok=proc && SUCCEEDED(proc(&argb,&opaque));
 if(unload) FreeLibrary(dll);
 if(ok) return ThemeRgb(argb&0xFFFFFF);
 DWORD fallback=GetSysColor(COLOR_HIGHLIGHT);
 return winrt::Windows::UI::Color{255,GetRValue(fallback),GetGValue(fallback),GetBValue(fallback)};
}
static MarkerPalette ResolveMarkerPalette() {
 auto accent=ThemeWindowsAccent();
 auto light=ThemeLightMode();
 MarkerPalette p{accent,ThemeRgb(light?0x666666:0xB0B0B0),accent};
 const auto& t=g_settings.themePreset;
 if(t==L"monochrome") p={ThemeRgb(light?0x404040:0xFFFFFF),ThemeRgb(light?0x606060:0xC0C0C0),ThemeRgb(light?0x202020:0xFFFFFF)};
 else if(t==L"emberveil") p={ThemeRgb(0xFFBC5E),ThemeRgb(0xB8A98A),ThemeRgb(0xD9A441)};
 else if(t==L"catppuccinMocha") p={ThemeRgb(0xCBA6F7),ThemeRgb(0x9399B2),ThemeRgb(0xF5C2E7)};
 else if(t==L"catppuccinLatte") p={ThemeRgb(0x8839EF),ThemeRgb(0x9CA0B0),ThemeRgb(0xEA76CB)};
 else if(t==L"catppuccinMacchiato") p={ThemeRgb(0xC6A0F6),ThemeRgb(0x939AB7),ThemeRgb(0xF5BDE6)};
 else if(t==L"catppuccinFrappe") p={ThemeRgb(0xCA9EE6),ThemeRgb(0x949CBB),ThemeRgb(0xF4B8E4)};
 else if(t==L"dracula") p={ThemeRgb(0xBD93F9),ThemeRgb(0x6272A4),ThemeRgb(0xFF79C6)};
 else if(t==L"gruvbox") p={ThemeRgb(0xFABD2F),ThemeRgb(0x928374),ThemeRgb(0xFE8019)};
 else if(t==L"nord") p={ThemeRgb(0x88C0D0),ThemeRgb(0x4C566A),ThemeRgb(0x81A1C1)};
 else if(t==L"solarized") p={ThemeRgb(0x268BD2),ThemeRgb(0x839496),ThemeRgb(0x2AA198)};
 else if(t==L"tokyoNight") p={ThemeRgb(0x7AA2F7),ThemeRgb(0x565F89),ThemeRgb(0xBB9AF7)};
 // 'custom' intentionally inherits Windows Default for empty overrides.
 winrt::Windows::UI::Color overrideColor{};
 if(TryParseColorString(g_settings.activeIndicatorColor,&overrideColor)) p.active=overrideColor;
 if(TryParseColorString(g_settings.inactiveMarkerColor,&overrideColor)) p.inactive=overrideColor;
 if(TryParseColorString(g_settings.hoverMarkerColor,&overrideColor)) p.hover=overrideColor;
 return p;
}
static std::wstring MarkerPaletteSignature(MarkerPalette const& p) {
 auto one=[](winrt::Windows::UI::Color c){return std::to_wstring(c.A)+L","+
  std::to_wstring(c.R)+L","+std::to_wstring(c.G)+L","+std::to_wstring(c.B);};
 return one(p.active)+L"|"+one(p.inactive)+L"|"+one(p.hover);
}
static void NativeUpdateTextOnUiThread() {
 if(!g_pill) return;
 auto text=FindNamed(g_pill,L"EmberveilDesktopText").try_as<TextBlock>();
 auto markers=FindNamed(g_pill,L"EmberveilMarkerPanel").try_as<StackPanel>();
 if(!text || !markers) return;
 const bool needNames = g_settings.indicatorMode == IndicatorMode::DesktopName ||
     (g_settings.indicatorMode == IndicatorMode::Markers && g_settings.markerTooltips);
 auto state=ReadDesktopStateSnapshot(needNames);
 // A transient partial registry update must not replace a valid widget with
 // an invented single-desktop state. The next event/tick retries the read.
 if(!state.valid) return;
 int count=state.desktopCount;
 int active=state.currentDesktop;
 const bool allowVisibility = !(g_settings.hideWhenSingleDesktop && count==1);
 if(g_contentAllowsVisibility != allowVisibility) {
  EMBER_LOG_INFO(L"Content visibility transition: count=%d hideSingle=%d allowed=%d placement=%s",
         count, g_settings.hideWhenSingleDesktop?1:0, allowVisibility?1:0, g_position.c_str());
 }
 g_contentAllowsVisibility = allowVisibility;
 if(!allowVisibility) {
  g_pill.Visibility(Visibility::Collapsed);
  return;
 }
 g_pill.Visibility(Visibility::Visible);
 MarkerPalette palette=ResolveMarkerPalette();
 bool markerMode=g_settings.indicatorMode==IndicatorMode::Markers;
 text.Visibility(markerMode?Visibility::Collapsed:Visibility::Visible);
 markers.Visibility(markerMode?Visibility::Visible:Visibility::Collapsed);
 // Preserve XAML controls across polling ticks. Recreating them every second
 // dismisses any open tooltip and resets its hover delay.
 const auto& names=state.names;
 std::wstring signature=std::to_wstring(count)+L"|"+std::to_wstring(active)+L"|"+
  std::to_wstring(static_cast<int>(g_settings.indicatorMode))+L"|"+
  std::to_wstring(g_settings.markerTooltips)+L"|"+g_settings.markerSymbol+L"|"+
  MarkerPaletteSignature(palette)+L"|"+
  std::to_wstring(g_settings.inactiveMarkerOpacity)+L"|"+
  std::to_wstring(g_settings.indicatorCharacterSpacing)+L"|"+
  std::to_wstring(g_settings.leftPadding)+L"|"+
  std::to_wstring(g_settings.rightPadding)+L"|"+
  std::to_wstring(static_cast<int>(g_settings.indicatorSize))+L"|"+
  std::to_wstring(static_cast<int>(g_settings.indicatorWeight));
 for(auto const& name:names) signature+=L"|"+name;
 static void* previousPill=nullptr;
 static std::wstring previousSignature;
 if(previousPill==winrt::get_abi(g_pill) && previousSignature==signature) return;
 previousPill=winrt::get_abi(g_pill);
 previousSignature=std::move(signature);
 text.Inlines().Clear();
 markers.Children().Clear();
 if(markerMode) {
  // Explicit spacer widths: XAML collapses leading ordinary spaces.
  const double spaceWidth=GetConfiguredIndicatorFontSize(13)*0.33;
  if(g_settings.leftPadding>0) {
   Controls::Border spacer;
   spacer.Width(g_settings.leftPadding*spaceWidth);
   spacer.IsHitTestVisible(false);
   markers.Children().Append(spacer);
  }
  for(int i=1;i<=count;++i) {
   // Border has no Button visual states (hover bubble / focus rectangle).
   Controls::Border marker;
   marker.Name(L"EmberveilMarkerButton");
   marker.Padding({4,4,4,4});
   marker.Margin({0,0,0,0});
   marker.MinHeight(26);
   marker.Background(SolidColorBrush(winrt::Windows::UI::Colors::Transparent()));
   marker.HorizontalAlignment(HorizontalAlignment::Center);
   marker.VerticalAlignment(VerticalAlignment::Center);
   TextBlock symbol;
   symbol.Text(GetConfiguredMarkerSymbol());
   symbol.FontSize(GetConfiguredIndicatorFontSize(13));
   symbol.FontWeight(GetConfiguredIndicatorFontWeight());
   symbol.IsHitTestVisible(false);
   if(i!=active) {
    auto c=palette.inactive;
    c.A=static_cast<BYTE>(c.A*std::clamp(g_settings.inactiveMarkerOpacity,0,100)/100);
    symbol.Foreground(SolidColorBrush(c));
   } else symbol.Foreground(SolidColorBrush(palette.active));
   marker.Child(symbol);
   if(g_settings.markerTooltips) {
    std::wstring tip=L"Desktop "+std::to_wstring(i);
    if(static_cast<size_t>(i)<=names.size() && !names[i-1].empty()) tip+=L" — "+names[i-1];
    Controls::ToolTipService::SetToolTip(marker,winrt::box_value(tip));
   }
   if(i!=active) {
    auto hoverColor=palette.hover;
    marker.PointerEntered([symbol,hoverColor](auto const&,auto const&) {
     symbol.Foreground(SolidColorBrush(hoverColor));
    });
    auto normalColor=palette.inactive;
    normalColor.A=static_cast<BYTE>(normalColor.A*std::clamp(g_settings.inactiveMarkerOpacity,0,100)/100);
    marker.PointerExited([symbol,normalColor](auto const&,auto const&) {
     symbol.Foreground(SolidColorBrush(normalColor));
    });
   }
   marker.Tapped([desktop=i](auto const&,auto const&) {
    SwitchToDesktopFromMarker(desktop);
   });
   markers.Children().Append(marker);
   if(i<count) {
    // Use hit-testable spacing, rather than a dead TextBlock between buttons.
    // The existing setting counts space characters; approximate their width.
    marker.Margin({0,0,(double)std::max(0,g_settings.indicatorCharacterSpacing)*spaceWidth,0});
   }
  }
  if(g_settings.rightPadding>0) {
   Controls::Border spacer;
   spacer.Width(g_settings.rightPadding*spaceWidth);
   spacer.IsHitTestVisible(false);
   markers.Children().Append(spacer);
  }
  EMBER_LOG_DEBUG(L"dev20 marker controls built: count=%d tooltip=%d",count,g_settings.markerTooltips?1:0);
 } else {
  std::wstring value;
  if(g_settings.indicatorMode==IndicatorMode::DesktopName)
   value=FormatDesktopNameOrNumber(active,names);
  else value=FormatDesktopNumber(active);
  Documents::Run run;run.Text(value);
  winrt::Windows::UI::Color c{};
  run.Foreground(SolidColorBrush(palette.active));
  text.Inlines().Append(run);
 }
}
// Measured overlay placement from Resource Pills: never shift the full-width
// application repeater or blindly overlap the tray. Hidden if no safe room.
struct DesktopButtonBounds {
 FrameworkElement firstAppButton{nullptr},firstAnyButton{nullptr};
 double firstApp=1e9,firstAny=1e9,appRight=0,launchRight=0;
 unsigned count=0;
};
static void MeasureDesktopButtons(FrameworkElement const& node,Grid const& root,
                                  DesktopButtonBounds& b,int depth=0) {
 if(!node || depth>24 || node.Visibility()!=Visibility::Visible ||
    node.Name()==kSlotName || node.Name()==kSecondarySlotName)return;
 auto name=std::wstring(node.Name());
 auto type=std::wstring(winrt::get_class_name(node));
 bool app=name.find(L"TaskbarButton")!=std::wstring::npos ||
          name.find(L"TaskListButton")!=std::wstring::npos;
 bool launch=name.find(L"LaunchListButton")!=std::wstring::npos ||
             type.find(L"LaunchListButton")!=std::wstring::npos;
 if((app||launch) && node.ActualWidth()>8 && node.ActualWidth()<200) {
  auto p=node.TransformToVisual(root).TransformPoint({0,0});
  double x=p.X,right=x+node.ActualWidth();
  if(std::isfinite(x)&&x>=0&&right<=root.ActualWidth()+1) {
   ++b.count; if(x<b.firstAny){b.firstAny=x;b.firstAnyButton=node;}
   if(app){if(x<b.firstApp){b.firstApp=x;b.firstAppButton=node;}b.appRight=std::max(b.appRight,right);}
   if(launch)b.launchRight=std::max(b.launchRight,right);
   return;
  }
 }
 for(int i=0;i<VisualTreeHelper::GetChildrenCount(node);++i)
  if(auto child=VisualTreeHelper::GetChild(node,i).try_as<FrameworkElement>())
   MeasureDesktopButtons(child,root,b,depth+1);
}
struct DesktopOverlayReservation {
 winrt::weak_ref<FrameworkElement> button;
 Thickness original{};
 double reserved=0;
};
static thread_local std::map<HWND,DesktopOverlayReservation> g_overlayReservations;
static void ReleaseDesktopOverlayReservation(HWND hwnd) {
 auto it=g_overlayReservations.find(hwnd);
 if(it==g_overlayReservations.end())return;
 auto& r=it->second;
 try {if(auto button=r.button.get()) {
  auto margin=button.Margin();
  // Remove only our contribution; preserve other mods' adjustments.
  margin.Left-=r.reserved;
  button.Margin(margin);
 }}catch(...) {EMBER_LOG_DEBUG(L"Overlay reservation cleanup failed");}
 g_overlayReservations.erase(it);
}
// Diagnostic sampling is per HWND and anchor: first four layout passes and
// then every 20th pass, so DbgView remains usable during live switching.
static thread_local std::map<HWND,std::pair<std::wstring,unsigned>> g_placementSamples;
static bool ShouldLogPlacement(HWND hwnd,std::wstring const& position) {
 if(!g_emberDebugLogging.load(std::memory_order_relaxed))return false;
 auto& sample=g_placementSamples[hwnd];
 if(sample.first!=position){sample.first=position;sample.second=0;}
 unsigned n=++sample.second;
 return n<=4 || n==8 || n%20==0;
}
static void LogPlacementGeometry(HWND hwnd,FrameworkElement const& root,
 FrameworkElement const& widget,std::wstring const& position,
 wchar_t const* phase,double reserved=0) {
 if(!ShouldLogPlacement(hwnd,position))return;
 try {
  auto grid=root.try_as<Grid>();
  auto tray=root?FindNamed(root,L"SystemTrayFrameGrid"):nullptr;
  if(!grid||!tray||!widget)return;
  auto t=tray.TransformToVisual(grid).TransformPoint({0,0});
  auto w=widget.TransformToVisual(grid).TransformPoint({0,0});
  RECT rect{};GetWindowRect(hwnd,&rect);
  double dpi=(double)GetDpiForWindow(hwnd);
  if(position==L"after-clock" || position==L"before-clock") {
   auto clock=FindClockAnchor(tray);
   double clockX=-1,clockW=-1;
   if(clock){auto cp=clock.TransformToVisual(grid).TransformPoint({0,0});clockX=cp.X;clockW=clock.ActualWidth();}
   EMBER_LOG_INFO(L"[ClockDiag] hwnd=%p phase=%s pos=%s rootRight=%.2f trayLeft=%.2f trayRight=%.2f clockLeft=%.2f clockRight=%.2f clockWidth=%.2f widgetLeft=%.2f widgetRight=%.2f widgetWidth=%.2f edgeClearance=%.2f",
     hwnd,phase,position.c_str(),grid.ActualWidth(),t.X,t.X+tray.ActualWidth(),clockX,clockX+clockW,clockW,w.X,w.X+widget.ActualWidth(),widget.ActualWidth(),grid.ActualWidth()-(w.X+widget.ActualWidth()));
  }
  EMBER_LOG_INFO(L"[PlacementDiag] hwnd=%p phase=%s pos=%s rootW=%.2f trayX=%.2f trayW=%.2f widgetX=%.2f widgetW=%.2f widgetDesired=%.2f widgetVisible=%d reserved=%.2f dpi=%.0f screen=[%ld,%ld,%ld,%ld]",
   hwnd,phase,position.c_str(),grid.ActualWidth(),t.X,tray.ActualWidth(),w.X,widget.ActualWidth(),widget.DesiredSize().Width,
   widget.Visibility()==Visibility::Visible?1:0,reserved,dpi,rect.left,rect.top,rect.right,rect.bottom);
 }catch(...){EMBER_LOG_DEBUG(L"Placement diagnostics measurement unavailable");}
}
static void UpdateDesktopOverlay(HWND hwnd,FrameworkElement const& root,
                                 FrameworkElement const& box,std::wstring const& position) {
 if(!box)return;
 auto grid=root.try_as<Grid>();
 auto tray=root?FindNamed(root,L"SystemTrayFrameGrid"):nullptr;
 if(!grid || !tray || grid.ActualWidth()<=0) {box.Visibility(Visibility::Collapsed);return;}
 box.Measure({10000,100});
 double width=box.DesiredSize().Width;
 if(!std::isfinite(width)||width<24) {
  // Content is not realized yet. Do not reserve an incomplete 0/16-DIP width.
  ReleaseDesktopOverlayReservation(hwnd);box.Visibility(Visibility::Collapsed);return;
 }
 DesktopButtonBounds b;MeasureDesktopButtons(root,grid,b);
 // Capture the geometry before this pass mutates any native button margin.
 double preFirstAny=b.firstAny,preFirstApp=b.firstApp;
 double preAppRight=b.appRight,preLaunchRight=b.launchRight;
 if(!b.count){ReleaseDesktopOverlayReservation(hwnd);box.Visibility(Visibility::Collapsed);return;}
 double trayLeft=tray.TransformToVisual(grid).TransformPoint({0,0}).X;
 // Resource Pills dev.45: reserve width in the first realized button's
 // margin, then measure again. Before-icons targets the first application;
 // Before Start targets the first launch/task button.
 bool reserve=position==L"before-icons" || position==L"before-start";
 FrameworkElement target=position==L"before-icons"?b.firstAppButton:b.firstAnyButton;
 double marginBefore=target?target.Margin().Left:0.0;
 double previousReserve=0.0;
 if(auto it=g_overlayReservations.find(hwnd);it!=g_overlayReservations.end())
  previousReserve=it->second.reserved;
 if(reserve && target) {
  if(g_overlayReservations[hwnd].button.get()!=target) {
   ReleaseDesktopOverlayReservation(hwnd);
   auto& fresh=g_overlayReservations[hwnd];fresh.button=winrt::make_weak(target);fresh.original=target.Margin();
  }
  auto& r=g_overlayReservations[hwnd];
  double wanted=width+4; // One shared 4-DIP clearance; avoid double-counting the gap.
  if(std::abs(r.reserved-wanted)>0.5) {
   auto margin=target.Margin();margin.Left+=wanted-r.reserved;
   target.Margin(margin);r.reserved=wanted;
   grid.UpdateLayout();b={};MeasureDesktopButtons(root,grid,b);
   trayLeft=tray.TransformToVisual(grid).TransformPoint({0,0}).X;
  }
 } else ReleaseDesktopOverlayReservation(hwnd);
 double buttonsRight=std::max(b.appRight,b.launchRight);
 double marginAfter=target?target.Margin().Left:0.0;
 double left=0;
 if(position==L"before-start")left=b.firstAny-width-2;
 else if(position==L"before-icons")left=b.firstAppButton?b.firstApp-width-2:buttonsRight+2;
 else if(position==L"after-icons")left=buttonsRight+1;
 else left=std::max((grid.ActualWidth()-width)/2.0+g_settings.horizontalOffset,buttonsRight+5);
 bool room=std::isfinite(left)&&left>=5&&left+width+5<=trayLeft;
 if(position==L"before-icons" && b.firstAppButton)room=room&&left>=b.launchRight+2;
 box.Visibility(room?Visibility::Visible:Visibility::Collapsed);
 if(g_emberDebugLogging.load(std::memory_order_relaxed)) {
  // Print these on each sampled pass; the general geometry log below is
  // sampled separately so this includes the actual button measurements.
  static thread_local std::map<HWND,std::pair<std::wstring,unsigned>> samples;
  auto& v=samples[hwnd];if(v.first!=position){v.first=position;v.second=0;}
  unsigned n=++v.second;
  if(n<=4 || n==8 || n%20==0) {
   double reserved=0;auto it=g_overlayReservations.find(hwnd);
   if(it!=g_overlayReservations.end())reserved=it->second.reserved;
   double firstButtonGap=position==L"before-start"?b.firstAny-(left+width):
                         position==L"before-icons"?b.firstApp-(left+width):
                         position==L"after-icons"?left-buttonsRight:0.0;
   double visualRight=left+width;
   double rawTargetX=position==L"before-start"?b.firstAny:
                     position==L"before-icons"?b.firstApp:buttonsRight;
   EMBER_LOG_INFO(L"[ReservationDiag] hwnd=%p pass=%u pos=%s preAny=%.2f postAny=%.2f preApp=%.2f postApp=%.2f preAppRight=%.2f postAppRight=%.2f preLaunchRight=%.2f postLaunchRight=%.2f marginBefore=%.2f marginAfter=%.2f oldReserve=%.2f newReserve=%.2f widgetWidth=%.2f visual=[%.2f,%.2f] neighborX=%.2f visualGap=%.2f trayLeft=%.2f room=%d",
     hwnd,n,position.c_str(),preFirstAny,b.firstAny,preFirstApp,b.firstApp,
     preAppRight,b.appRight,preLaunchRight,b.launchRight,marginBefore,marginAfter,
     previousReserve,reserved,width,left,visualRight,rawTargetX,firstButtonGap,trayLeft,room?1:0);
   EMBER_LOG_INFO(L"[PlacementDiag] hwnd=%p pass=%u pos=%s firstAny=%.2f firstApp=%.2f appRight=%.2f launchRight=%.2f trayLeft=%.2f pillW=%.2f targetLeft=%.2f gap=%.2f reserve=%.2f buttons=%u room=%d",
    hwnd,n,position.c_str(),b.firstAny,b.firstApp,b.appRight,b.launchRight,trayLeft,width,left,
    position==L"after-icons"?left-buttonsRight:position==L"before-start"?b.firstAny-(left+width):position==L"before-icons"?b.firstApp-(left+width):0.0,
    reserved,b.count,room?1:0);
  }
 }
 if(!room)return;
 // Root Grid horizontally centers the overlay by default.
 auto translate=box.RenderTransform().try_as<TranslateTransform>();
 if(!translate){translate=TranslateTransform();box.RenderTransform(translate);}
 translate.X(left-(grid.ActualWidth()-width)/2.0);
 LogPlacementGeometry(hwnd,root,box,position,L"overlay",g_overlayReservations.count(hwnd)?g_overlayReservations[hwnd].reserved:0);
}
static void NativeRemoveOnUiThread() {
 ReleaseDesktopOverlayReservation(taskwin::FindCurrentProcessTaskbarWnd());
 RestoreBeforeIconsReservation();
 auto parent=g_parent.get();
 if(parent) {
  for(int i=(int)parent.Children().Size()-1;i>=0;--i) {
   auto fe=parent.Children().GetAt(i).try_as<FrameworkElement>();
   if(fe && fe.Name()==kSlotName) parent.Children().RemoveAt(i);
  }
  if(!g_lease.markerName.empty() && !slot::Release(parent,g_lease))
   EMBER_LOG_ERROR(L"Old slot lease unavailable after taskbar recreation");
 }
 g_parent={};g_placeholder={};g_pill=nullptr;g_lease={};
}
static void NativeInsertOnUiThread() {
 if(g_nativeStop.load() || !g_showPrimary.load()) return;
 int index=-1;
 auto parent=ResolvePositionParent(index);
 if(!parent) return;
 for(auto child:parent.Children()) {
  auto fe=child.try_as<FrameworkElement>();
  if(fe && fe.Name()==kSlotName) return;
 }
 Grid box;box.Name(kSlotName);
 box.Height(30);box.VerticalAlignment(VerticalAlignment::Center);
 box.HorizontalAlignment(HorizontalAlignment::Center);
 // Enable hit testing for independent marker buttons.
 box.IsHitTestVisible(g_settings.indicatorMode==IndicatorMode::Markers);
 TextBlock label;label.Name(L"EmberveilDesktopText");
 label.FontSize(GetConfiguredIndicatorFontSize(13));
 label.FontWeight(GetConfiguredIndicatorFontWeight());
 label.VerticalAlignment(VerticalAlignment::Center);
 label.HorizontalAlignment(HorizontalAlignment::Center);
 label.Margin({8,0,8,0});
 label.IsTextSelectionEnabled(false);
 box.Margin({(g_position==L"center" || g_position==L"after-icons" || g_position==L"before-start" || g_position==L"before-icons") ? 0.0 : (double)(g_settings.placementMarginLeft+g_settings.nativeMarginLeft), (double)(g_settings.placementMarginTop+g_settings.nativeMarginTop), (g_position==L"center" || g_position==L"after-icons" || g_position==L"before-start" || g_position==L"before-icons") ? 0.0 : (double)(g_settings.placementMarginRight+g_settings.nativeMarginRight), (double)(g_settings.placementMarginBottom+g_settings.nativeMarginBottom)});
 box.Children().Append(label);
 StackPanel markerPanel;
 markerPanel.Name(L"EmberveilMarkerPanel");
 markerPanel.Orientation(Controls::Orientation::Horizontal);
 markerPanel.VerticalAlignment(VerticalAlignment::Center);
 markerPanel.HorizontalAlignment(HorizontalAlignment::Center);
 markerPanel.Margin({8,0,8,0});
 box.Children().Append(markerPanel);
 // Width is based on content; centered overlays use a fixed conservative width
 // to avoid the full-width root Grid swallowing pointer input.
 if(g_position==L"center" || g_position==L"after-icons" || g_position==L"before-start" || g_position==L"before-icons") {
  auto grid=parent.try_as<Grid>();if(!grid)return;
  // Both overlays size to their actual marker content. A fixed 150-DIP
  // width clips long desktop names and larger marker configurations.
  Grid::SetColumn(box,0);
  Grid::SetColumnSpan(box,std::max(1,(int)grid.ColumnDefinitions().Size()));
  Grid::SetRowSpan(box,std::max(1,(int)grid.RowDefinitions().Size()));
  Canvas::SetZIndex(box,100);
  grid.Children().Append(box);
 } else {
  if(!slot::AcquireAt(parent,index,kLeaseName,g_lease))return;
  bool ok=false;
  try {ok=slot::PlaceChild(parent,g_lease,box);}catch(...) {slot::Release(parent,g_lease);throw;}
  if(!ok){slot::Release(parent,g_lease);return;}
 }
 g_parent=parent;g_placeholder=box;g_pill=box;
 NativeUpdateTextOnUiThread();
 if(g_position==L"center" || g_position==L"after-icons" || g_position==L"before-start" || g_position==L"before-icons")
  UpdateDesktopOverlay(taskwin::FindCurrentProcessTaskbarWnd(),LiveTaskbarRoot(),g_pill,g_position);
 UpdateBeforeIconsOnUiThread();
 LogPlacementGeometry(taskwin::FindCurrentProcessTaskbarWnd(),LiveTaskbarRoot(),g_pill,g_position,L"insert");
 EMBER_LOG_INFO(L"Native indicator inserted at %s",g_position.c_str());
}
static void NativeTickOnUiThread() {
 if(g_nativeStop.load())return;
 if(!g_showPrimary.load()){if(g_pill)NativeRemoveOnUiThread();return;}
 auto parent=g_parent.get();
 bool found=false;
 if(parent)for(auto child:parent.Children()) {
  auto fe=child.try_as<FrameworkElement>();
  if(fe && fe.Name()==kSlotName){found=true;break;}
 }
 if(g_nativeRebuild.exchange(false) || !found) {
  NativeRemoveOnUiThread();NativeInsertOnUiThread();
 }
 NativeUpdateTextOnUiThread();
 if(g_position==L"center" || g_position==L"after-icons" || g_position==L"before-start" || g_position==L"before-icons")
  UpdateDesktopOverlay(taskwin::FindCurrentProcessTaskbarWnd(),LiveTaskbarRoot(),g_pill,g_position);
 if(g_position==L"before-clock" || g_position==L"after-clock" || g_position==L"before-tray")
  LogPlacementGeometry(taskwin::FindCurrentProcessTaskbarWnd(),LiveTaskbarRoot(),g_pill,g_position,L"tick");
 UpdateBeforeIconsOnUiThread();
}
// Desktop-change wakes refresh content only. Periodic ticks still own layout
// recalculation, taskbar reconstruction and missed-change recovery.
static void NativeContentTickOnUiThread() {
 if(g_nativeStop.load()) return;
 if(g_nativeRebuild.load() || !g_pill) {
  NativeTickOnUiThread();
  return;
 }
 NativeUpdateTextOnUiThread();
}
// Read-only monitor inventory. XAML roots must be resolved on each taskbar's
// owning UI thread; this phase intentionally does not instantiate indicators.
static void NativeProbeSecondaryTaskbars() {
    if (!g_emberDebugLogging.load(std::memory_order_relaxed)) return;
    EnumWindows([](HWND hwnd, LPARAM)->BOOL {
        DWORD pid=0;
        wchar_t klass[64]{};
        if (GetWindowThreadProcessId(hwnd,&pid)==0 || pid!=GetCurrentProcessId() ||
            !GetClassNameW(hwnd,klass,ARRAYSIZE(klass)) ||
            _wcsicmp(klass,L"Shell_SecondaryTrayWnd")!=0) return TRUE;
        HWND worker=FindWindowExW(hwnd,nullptr,L"WorkerW",nullptr);
        EMBER_LOG_DEBUG(L"Secondary taskbar hwnd=%p thread=%lu worker=%p symbols=%d",
            hwnd,GetWindowThreadProcessId(hwnd,nullptr),worker,
            folder_menus_taskbar_xaml::CSecondaryTaskBand_GetTaskbarHost_Original &&
            folder_menus_taskbar_xaml::CSecondaryTaskBand_ITaskListWndSite_vftable ? 1:0);
        return TRUE;
    },0);
}

// dev.10: one independently owned, native XAML indicator per secondary taskbar.
// Initial scope: before-tray only. Each callback runs on that taskbar's UI thread.
struct SecondaryIndicator {
 HWND hwnd{};
 slot::Lease lease{};
 winrt::weak_ref<Panel> parent;
 winrt::weak_ref<FrameworkElement> widget;
 std::wstring signature;
 std::wstring position;
};
static thread_local std::map<HWND,SecondaryIndicator> g_secondaryIndicators;


static void SecondaryRemoveOnUiThread(SecondaryIndicator& item) {
 ReleaseDesktopOverlayReservation(item.hwnd);
 try {
  if(auto parent=item.parent.get()) {
   for(int i=(int)parent.Children().Size()-1;i>=0;--i) {
    auto fe=parent.Children().GetAt(i).try_as<FrameworkElement>();
    if(fe && fe.Name()==kSecondarySlotName)parent.Children().RemoveAt(i);
   }
   if(!item.lease.markerName.empty())slot::Release(parent,item.lease);
  }
 }catch(...){NativeLogException(L"Secondary remove");}
 item.parent={};item.widget={};item.lease={};item.signature.clear();item.position.clear();
}
// Secondary taskbars can contain an extra trailing tray column after the clock.
// Inserting a new column there pushes the clock and the indicator to the edge.
// Anchor the secondary indicator to the measured clock instead, without altering
// the tray's column definitions. The primary clock insertion remains unchanged.
static void UpdateSecondaryClockOverlay(HWND hwnd,FrameworkElement const& root,
                                        FrameworkElement const& box) {
 if(!root || !box)return;
 auto grid=root.try_as<Grid>();
 auto tray=FindNamed(root,L"SystemTrayFrameGrid");
 auto clock=tray?FindClockAnchor(tray):nullptr;
 if(!grid || !clock || grid.ActualWidth()<=0)return;
 box.Measure({10000,100});
 double width=box.DesiredSize().Width;
 if(!std::isfinite(width)||width<24) {box.Visibility(Visibility::Collapsed);return;}
 auto cp=clock.TransformToVisual(grid).TransformPoint({0,0});
 double clockRight=cp.X+clock.ActualWidth();
 double left=clockRight+4;
 double rightLimit=grid.ActualWidth()-4;
 bool room=std::isfinite(left)&&left>=0&&left+width<=rightLimit;
 box.Visibility(room?Visibility::Visible:Visibility::Collapsed);
 if(!room) {
  if(g_emberDebugLogging.load(std::memory_order_relaxed))
   EMBER_LOG_INFO(L"[ClockFix] hwnd=%p no room clockRight=%.2f width=%.2f rightLimit=%.2f",
                  hwnd,clockRight,width,rightLimit);
  return;
 }
 auto translate=box.RenderTransform().try_as<TranslateTransform>();
 if(!translate){translate=TranslateTransform();box.RenderTransform(translate);}
 translate.X(left-(grid.ActualWidth()-width)/2.0);
 LogPlacementGeometry(hwnd,root,box,L"after-clock",L"clock-overlay");
}
static void SecondaryTickOnUiThread(void* parameter) {
 HWND hwnd=*static_cast<HWND*>(parameter);
 if(g_nativeStop.load())return;
 try {
  auto root=taskxaml::GetSecondaryTaskbarXamlRoot(hwnd);
  auto content=root?root.Content().try_as<FrameworkElement>():nullptr;
  auto tray=content?FindNamed(content,L"SystemTrayFrameGrid").try_as<Panel>():nullptr;
  auto& item=g_secondaryIndicators[hwnd];item.hwnd=hwnd;
  auto position=EffectiveSecondaryPosition();
  if(position==L"hidden") {if(item.widget.get())SecondaryRemoveOnUiThread(item);return;}
  int index=-1;
  auto parent=position==L"after-clock" ? content.try_as<Grid>().try_as<Panel>() : ResolveMonitorPosition(hwnd,content,position,index);
  if(!parent || parent.ActualWidth()<=0)return;
  if(item.position!=position && item.widget.get())SecondaryRemoveOnUiThread(item);
  auto box=item.widget.get();
  if(box && item.parent.get()!=parent) {SecondaryRemoveOnUiThread(item);box=nullptr;}
  if(!box) {
   Grid grid;grid.Name(kSecondarySlotName);grid.Height(30);
   grid.VerticalAlignment(VerticalAlignment::Center);
   grid.HorizontalAlignment(HorizontalAlignment::Center);
   grid.Margin({(position==L"after-clock" || position==L"before-start" || position==L"before-icons" || position==L"after-icons" || position==L"center") ? 0.0 : (double)(g_settings.placementMarginLeft+g_settings.nativeMarginLeft),
    (double)(g_settings.placementMarginTop+g_settings.nativeMarginTop),
    (position==L"after-clock" || position==L"before-start" || position==L"before-icons" || position==L"after-icons" || position==L"center") ? 0.0 : (double)(g_settings.placementMarginRight+g_settings.nativeMarginRight),
    (double)(g_settings.placementMarginBottom+g_settings.nativeMarginBottom)});
   grid.IsHitTestVisible(g_settings.indicatorMode==IndicatorMode::Markers);
   StackPanel panel;panel.Name(L"EmberveilSecondaryMarkers");
   panel.Orientation(Controls::Orientation::Horizontal);
   panel.VerticalAlignment(VerticalAlignment::Center);
   grid.Children().Append(panel);
   TextBlock label;label.Name(L"EmberveilSecondaryText");
   label.FontSize(GetConfiguredIndicatorFontSize(13));
   label.FontWeight(GetConfiguredIndicatorFontWeight());
   label.Margin({8,0,8,0});label.VerticalAlignment(VerticalAlignment::Center);
   grid.Children().Append(label);
   bool overlay=position==L"before-start" || position==L"before-icons" || position==L"after-icons" || position==L"center" || position==L"after-clock";
   if(overlay) {
    auto rootGrid=parent.try_as<Grid>();if(!rootGrid)return;
    Grid::SetColumn(grid,0);
    Grid::SetColumnSpan(grid,std::max(1,(int)rootGrid.ColumnDefinitions().Size()));
    Grid::SetRowSpan(grid,std::max(1,(int)rootGrid.RowDefinitions().Size()));
    Canvas::SetZIndex(grid,100);rootGrid.Children().Append(grid);
   } else {
    if(!slot::AcquireAt(parent,index,kSecondaryLeaseName,item.lease))return;
    if(!slot::PlaceChild(parent,item.lease,grid)) {
     slot::Release(parent,item.lease);item.lease={};return;
    }
   }
   item.parent=parent;item.widget=grid;item.position=position;box=grid;
   LogPlacementGeometry(hwnd,content,grid,position,L"insert");
   EMBER_LOG_INFO(L"Secondary indicator inserted hwnd=%p at %s",hwnd,position.c_str());
  }
  const bool needNames=g_settings.indicatorMode==IndicatorMode::DesktopName || g_settings.markerTooltips;
  auto state=ReadDesktopStateSnapshot(needNames);
  if(!state.valid)return;
  bool visible=!(g_settings.hideWhenSingleDesktop && state.desktopCount==1);
  box.Visibility(visible?Visibility::Visible:Visibility::Collapsed);
  if(!visible)return;
  if(position==L"after-clock")
   UpdateSecondaryClockOverlay(hwnd,content,box);
  else if(position==L"before-start" || position==L"before-icons" || position==L"after-icons" || position==L"center")
   UpdateDesktopOverlay(hwnd,content,box,position);
  else LogPlacementGeometry(hwnd,content,box,position,L"tick");
  auto palette=ResolveMarkerPalette();
  std::wstring sig=std::to_wstring(state.desktopCount)+L"|"+std::to_wstring(state.currentDesktop)+L"|"+
   std::to_wstring((int)g_settings.indicatorMode)+L"|"+g_settings.markerSymbol+L"|"+
   MarkerPaletteSignature(palette)+L"|"+std::to_wstring(g_settings.markerTooltips);
  for(auto const& name:state.names)sig+=L"|"+name;
  if(item.signature==sig)return;
  item.signature=std::move(sig);
  auto panel=FindNamed(box,L"EmberveilSecondaryMarkers").try_as<StackPanel>();
  auto label=FindNamed(box,L"EmberveilSecondaryText").try_as<TextBlock>();
  if(!panel||!label)return;
  panel.Children().Clear();
  bool markers=g_settings.indicatorMode==IndicatorMode::Markers;
  panel.Visibility(markers?Visibility::Visible:Visibility::Collapsed);
  label.Visibility(markers?Visibility::Collapsed:Visibility::Visible);
  if(!markers) {
   label.Text(g_settings.indicatorMode==IndicatorMode::DesktopName?
    FormatDesktopNameOrNumber(state.currentDesktop,state.names):FormatDesktopNumber(state.currentDesktop));
   label.Foreground(SolidColorBrush(palette.active));
  }else {
   for(int i=1;i<=state.desktopCount;++i) {
    Controls::Border marker;
    marker.Padding({4,4,4,4});marker.MinHeight(26);
    marker.Background(SolidColorBrush(winrt::Windows::UI::Colors::Transparent()));
    TextBlock symbol;symbol.Text(GetConfiguredMarkerSymbol());
    symbol.FontSize(GetConfiguredIndicatorFontSize(13));
    symbol.FontWeight(GetConfiguredIndicatorFontWeight());symbol.IsHitTestVisible(false);
    auto normal=i==state.currentDesktop?palette.active:palette.inactive;
    if(i!=state.currentDesktop)
     normal.A=(BYTE)(normal.A*std::clamp(g_settings.inactiveMarkerOpacity,0,100)/100);
    symbol.Foreground(SolidColorBrush(normal));marker.Child(symbol);
    if(g_settings.markerTooltips){
     std::wstring tip=L"Desktop "+std::to_wstring(i);
     if((size_t)i<=state.names.size()&&!state.names[i-1].empty())tip+=L" — "+state.names[i-1];
     Controls::ToolTipService::SetToolTip(marker,winrt::box_value(tip));
    }
    if(i!=state.currentDesktop){
     auto hover=palette.hover;
     marker.PointerEntered([symbol,hover](auto const&,auto const&){symbol.Foreground(SolidColorBrush(hover));});
     marker.PointerExited([symbol,normal](auto const&,auto const&){symbol.Foreground(SolidColorBrush(normal));});
    }
    marker.Tapped([desktop=i](auto const&,auto const&){SwitchToDesktopFromMarker(desktop);});
    if(i<state.desktopCount)marker.Margin({0,0,(double)std::max(0,g_settings.indicatorCharacterSpacing)*GetConfiguredIndicatorFontSize(13)*0.33,0});
    panel.Children().Append(marker);
   }
  }
 }catch(...){NativeLogException(L"Secondary indicator tick");}
}
static void SecondaryRemoveCallback(void* parameter) {
 HWND hwnd=*static_cast<HWND*>(parameter);
 auto it=g_secondaryIndicators.find(hwnd);
 if(it!=g_secondaryIndicators.end()){SecondaryRemoveOnUiThread(it->second);g_secondaryIndicators.erase(it);}
}
static void NativeTickSecondaryTaskbars(bool remove=false) {
 // Stage 1 secondary tray positions; visibility and live relocation.
 EnumWindows([](HWND hwnd,LPARAM param)->BOOL {
  DWORD pid=0;wchar_t klass[64]{};
  if(!GetWindowThreadProcessId(hwnd,&pid)||pid!=GetCurrentProcessId()||
     !GetClassNameW(hwnd,klass,ARRAYSIZE(klass))||
     _wcsicmp(klass,L"Shell_SecondaryTrayWnd"))return TRUE;
  bool remove=*reinterpret_cast<bool*>(param);
  folder_menus_dispatch::RunFromWindowThread(hwnd,
   remove?SecondaryRemoveCallback:SecondaryTickOnUiThread,&hwnd,
   L"Windhawk_EmberveilDesktopIndicator_SecondaryTick");
  return TRUE;
 },reinterpret_cast<LPARAM>(&remove));
}

static DWORD WINAPI NativeWorker(void*) {
 HANDLE waits[]={g_nativeStopEvent,g_nativeContentWakeEvent};
 // Probe only after symbol resolution and on secondary UI threads.
 NativeTickSecondaryTaskbars();
 // Keep the first full tick immediately after startup.
 NativeDispatch([](void*){NativeTickOnUiThread();});
 while(!g_nativeStop.load()) {
  DWORD result=WaitForMultipleObjects(2,waits,FALSE,1000);
  if(result==WAIT_OBJECT_0) break;
  if(result==WAIT_OBJECT_0+1) {
   NativeDispatch([](void*){NativeContentTickOnUiThread();});
   NativeTickSecondaryTaskbars();
  } else if(result==WAIT_TIMEOUT) {
   NativeDispatch([](void*){NativeTickOnUiThread();});
   NativeTickSecondaryTaskbars();
  } else {
   EMBER_LOG_ERROR(L"Native worker wait failed: %lu",result);
   break;
  }
 }
 NativeTickSecondaryTaskbars(true);
 return 0;
}


namespace desktop_animation {
using WindowCommit = HRESULT (*)(void*, void*, unsigned, float, bool);
using AddTransition = HRESULT (*)(void*, unsigned, unsigned, TA_TIMINGFUNCTION*, void*,
                                  void*, const double*, unsigned, bool);
WindowCommit g_originalCommit;
AddTransition g_originalTransition;
std::atomic<unsigned> g_duration{750};
std::atomic<unsigned> g_keyboardDuration{750};
enum class Curve { Native, Linear, EaseOut };
std::atomic<Curve> g_curve{Curve::Native};
std::atomic<bool> g_forceAnimations{true};
bool g_keyboardHooksAvailable = false;
std::atomic<bool> g_enabled{true};
thread_local unsigned g_hotkeyCommitDepth = 0;
thread_local unsigned g_commitDepth = 0;
thread_local unsigned g_keyboardDepth = 0;
using HotkeyCommit = HRESULT (*)(void*, void*, float);
using CycleInDirection = HRESULT (*)(void*, int);
HotkeyCommit g_originalHotkeyCommit;
CycleInDirection g_originalCycle;
decltype(&SystemParametersInfoW) g_originalSystemParametersInfo;


using AnimationsEnabledFunction = bool (*)(void*);
AnimationsEnabledFunction g_animationsEnabledOriginal;
bool AnimationsEnabledHook(void* self) {
    bool enabled = g_animationsEnabledOriginal(self);
    if (g_enabled.load() && g_forceAnimations.load() && (g_commitDepth || g_keyboardDepth) && !enabled) {
        EMBER_LOG_INFO(L"Allowing animation inside desktop transition");
        return true;
    }
    return enabled;
}

struct DepthScope {
    unsigned& depth;
    explicit DepthScope(unsigned& value) : depth(value) { ++depth; }
    ~DepthScope() { --depth; }
    DepthScope(const DepthScope&) = delete;
    DepthScope& operator=(const DepthScope&) = delete;
};

HRESULT CommitHook(void* self, void* handler, unsigned token,
                   float target, bool touch) {
    // FinishSwipe passes false; FinishTouchSwipe passes true.
    if (touch || !g_enabled.load()) return g_originalCommit(self, handler, token, target, touch);
        EMBER_LOG_DEBUG(L"gesture window commit: target=%f touch=%d token=%u", target, touch, token);
    DepthScope scope(g_commitDepth);
    return g_originalCommit(self, handler, token, target, touch);
}

HRESULT HotkeyCommitHook(void* self, void* animator, float target) {
    if (!g_enabled.load()) return g_originalHotkeyCommit(self, animator, target);
    EMBER_LOG_DEBUG(L"keyboard window commit: target=%f", target);
    DepthScope keyboardScope(g_hotkeyCommitDepth);
    DepthScope scope(g_commitDepth);
    return g_originalHotkeyCommit(self, animator, target);
}

HRESULT CycleInDirectionHook(void* self, int direction) {
    // Windows checks SPI_GETCLIENTAREAANIMATION before choosing its animated path.
    // Keep this permission scoped separately from duration changes in Commit.
    if (!g_enabled.load()) return g_originalCycle(self, direction);
    DepthScope scope(g_keyboardDepth);
    return g_originalCycle(self, direction);
}

BOOL WINAPI SystemParametersInfoHook(UINT action, UINT param, PVOID value, UINT flags) {
    if (g_enabled.load() && g_keyboardHooksAvailable && g_forceAnimations.load() && g_keyboardDepth && action == SPI_GETCLIENTAREAANIMATION && value) {
        *static_cast<BOOL*>(value) = TRUE;
        return TRUE;
    }
    return g_originalSystemParametersInfo(action, param, value, flags);
}

HRESULT TransitionHook(void* self, unsigned delayMs, unsigned durationMs,
                       TA_TIMINGFUNCTION* timing, void* storyboard, void* variable,
                       const double* values, unsigned count, bool force) {
    static TA_CUBIC_BEZIER ease{{TTFT_CUBIC_BEZIER}, .22f, 1.f, .36f, 1.f};
    static TA_CUBIC_BEZIER linear{{TTFT_CUBIC_BEZIER}, 1.f/3.f, 1.f/3.f, 2.f/3.f, 2.f/3.f};
    // Only animated cubic transitions within a gesture or hotkey commit are changed.
    // Instantaneous updates during dragging stay untouched.
    if (g_enabled.load() && g_commitDepth && durationMs && timing &&
        timing->eTimingFunctionType == TTFT_CUBIC_BEZIER) {
        unsigned chosen = g_hotkeyCommitDepth ? g_keyboardDuration.load() : g_duration.load();
                EMBER_LOG_DEBUG(L"settle transition: delay=%u native=%u requested=%u dimensions=%u",
                   delayMs, durationMs, chosen, count);
        durationMs = chosen;
        if (g_curve.load() == Curve::Linear) timing = &linear.header;
        else if (g_curve.load() == Curve::EaseOut) timing = &ease.header;
    }
    return g_originalTransition(self, delayMs, durationMs, timing, storyboard,
                                variable, values, count, force);
}

void LoadAnimationSettings() {
    g_duration = std::clamp(Wh_GetIntSetting(L"Transitions.durationMs"), 150, 5000);
    g_keyboardDuration = std::clamp(Wh_GetIntSetting(L"Transitions.keyboardDurationMs"), 150, 5000);
    PCWSTR curve = Wh_GetStringSetting(L"Transitions.transitionCurve");
    g_curve = wcscmp(curve, L"linear") == 0 ? Curve::Linear :
              wcscmp(curve, L"easeOut") == 0 ? Curve::EaseOut : Curve::Native;
    Wh_FreeStringSetting(curve);
    g_forceAnimations = Wh_GetIntSetting(L"Transitions.forceAnimations") != 0;
    g_enabled = Wh_GetIntSetting(L"Transitions.smoothDesktopTransitions") != 0;
}

bool InitAnimationHooks() {
    EMBER_LOG_INFO(L"Optional native desktop animation hooks initializing");
    LoadAnimationSettings();
    HMODULE shell = LoadLibraryExW(L"twinui.pcshell.dll", nullptr,
                                   LOAD_LIBRARY_SEARCH_SYSTEM32);
    HMODULE thumbnails = LoadLibraryExW(L"twinui.dll", nullptr,
                                        LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!shell || !thumbnails) {
        EMBER_LOG_ERROR(L"Failed to load required shell modules");
        return FALSE;
    }

    // twinui.pcshell.dll
    WindhawkUtils::SYMBOL_HOOK shellHooks[] = {
        {{
             L"public: long __cdecl VirtualDesktopGestureWindow::Commit(struct IVirtualDesktopGestureHandlerPrivate *,unsigned int,float,bool)",
         },
         &g_originalCommit,
         CommitHook},
        {{
             L"public: long __cdecl VirtualDesktopHotKeyWindow::Commit(struct IVirtualDesktopSwitchAnimator2 *,float)",
         },
         &g_originalHotkeyCommit,
         HotkeyCommitHook, true},
        {{
             L"private: long __cdecl CVirtualDesktopHotkeyHandler::_CycleInDirection(enum VirtualDesktopSwitchDirection)",
         },
         &g_originalCycle,
         CycleInDirectionHook, true},
    };
    WindhawkUtils::SYMBOL_HOOK twinuiDllHooks[] = {
        {{
             L"private: long __cdecl CDCompAbstractThumbnail::_AddTransition(unsigned int,unsigned int,struct TA_TIMINGFUNCTION *,struct IUIAnimationStoryboard2 *,struct IUIAnimationVariable2 *,double * const,unsigned int,bool)",
         },
         &g_originalTransition,
         TransitionHook},
        {{
             L"public: virtual bool __cdecl CSwitchThumbnailDeviceManager::AnimationsEnabled(void)",
         },
         &g_animationsEnabledOriginal,
         AnimationsEnabledHook},
    };
    if (!WindhawkUtils::HookSymbols(shell, shellHooks, ARRAYSIZE(shellHooks)) ||
        !WindhawkUtils::HookSymbols(thumbnails, twinuiDllHooks, ARRAYSIZE(twinuiDllHooks))) {
        EMBER_LOG_ERROR(L"Failed to hook required symbols; initialization aborted.");
        return FALSE;
    }
    g_keyboardHooksAvailable = g_originalHotkeyCommit && g_originalCycle;
    if (!g_keyboardHooksAvailable) {
        EMBER_LOG_ERROR(L"Keyboard symbols unavailable; touchpad support remains active");
    }
    if (g_keyboardHooksAvailable && !WindhawkUtils::SetFunctionHook(SystemParametersInfoW,
                                        SystemParametersInfoHook,
                                        &g_originalSystemParametersInfo)) {
        EMBER_LOG_ERROR(L"Failed to hook the desktop hotkey animation preference query");
        g_keyboardHooksAvailable = false;
    }
    EMBER_LOG_INFO(L"Native desktop animations ready; duration=%u ms", g_duration.load());
    return TRUE;
}


} // namespace desktop_animation

BOOL Wh_ModInit() {
    g_unloading = false;
    LoadSettings();
    g_showPrimary=Wh_GetIntSetting(L"Placement.showPrimary")!=0;
    g_showSecondary=Wh_GetIntSetting(L"Placement.showSecondary")!=0;
    { auto v=StringSetting::make(L"Placement.secondaryPosition");g_secondaryPosition=v.get();
   if(g_secondaryPosition==L"after-tray")g_secondaryPosition=L"after-clock"; }
    g_position=NativePosition();
    g_winVersion = GetExplorerVersion();
    if (g_winVersion < WinVersion::Win11) {
        EMBER_LOG_ERROR(L"Only Windows 11 is supported");
        return FALSE;
    }

    g_currentDesktopNumber.store(ReadCurrentDesktopNumberFromRegistry());

    // Animation is optional: unsupported private symbols must not break the indicator.
    if (!desktop_animation::InitAnimationHooks()) {
        EMBER_LOG_INFO(L"Native animation hooks unavailable; indicator remains active");
    }

    // XAML-only: legacy clock rendering and its unused hooks have been removed.
    // Desktop notifications and polling still update shared state; the native
    // worker retains its known-good refresh cadence pending the A2 audit.

    EnsureDesktopChangeTracking();
    NativeProbeSecondaryTaskbars();
    folder_menus_dispatch::SetExceptionLogger(NativeLogException);
    if(!taskxaml::HookTaskbarSymbols([](){g_nativeRebuild.store(true);}))
      EMBER_LOG_ERROR(L"Native taskbar hooks unavailable");
    return TRUE;
}

void Wh_ModSettingsChanged() {
    desktop_animation::LoadAnimationSettings();
    NativeDispatch([](void*){NativeRemoveOnUiThread();});
    LoadSettings();
    g_showPrimary=Wh_GetIntSetting(L"Placement.showPrimary")!=0;
    g_showSecondary=Wh_GetIntSetting(L"Placement.showSecondary")!=0;
    { auto v=StringSetting::make(L"Placement.secondaryPosition");g_secondaryPosition=v.get();
   if(g_secondaryPosition==L"after-tray")g_secondaryPosition=L"after-clock"; }
    g_position=NativePosition();
    g_nativeRebuild.store(true);
    if(g_nativeContentWakeEvent) SetEvent(g_nativeContentWakeEvent);
    EnsureDesktopChangeTracking();
}

void Wh_ModAfterInit() {
    EnsureDesktopChangeTracking();
    if(!g_nativeWorker) {
        g_nativeStop=false;
        g_nativeStopEvent=CreateEventW(nullptr,TRUE,FALSE,nullptr);
        g_nativeContentWakeEvent=CreateEventW(nullptr,FALSE,FALSE,nullptr);
        if(g_nativeStopEvent && g_nativeContentWakeEvent)
            g_nativeWorker=CreateThread(nullptr,0,NativeWorker,nullptr,0,nullptr);
        if(!g_nativeWorker) {
            EMBER_LOG_ERROR(L"Failed to start native refresh worker");
            if(g_nativeContentWakeEvent){CloseHandle(g_nativeContentWakeEvent);g_nativeContentWakeEvent=nullptr;}
            if(g_nativeStopEvent){CloseHandle(g_nativeStopEvent);g_nativeStopEvent=nullptr;}
        }
    }
}

void Wh_ModBeforeUninit() {
    g_nativeStop=true;
    if(g_nativeStopEvent)SetEvent(g_nativeStopEvent);
    if(g_nativeWorker){WaitForSingleObject(g_nativeWorker,INFINITE);CloseHandle(g_nativeWorker);g_nativeWorker=nullptr;}
    if(g_nativeStopEvent){CloseHandle(g_nativeStopEvent);g_nativeStopEvent=nullptr;}
    NativeDispatch([](void*){NativeRemoveOnUiThread();});
    g_unloading = true;
    StopVirtualDesktopNotificationThread();
    StopDesktopPollThread();
    if(g_nativeContentWakeEvent){CloseHandle(g_nativeContentWakeEvent);g_nativeContentWakeEvent=nullptr;}
}

void Wh_ModUninit() {
    // Native XAML cleanup is performed in Wh_ModBeforeUninit.
}

