// @id tray-overflow-sort
// @name Tray Overflow Sort
// @description Sort hidden tray icons alphabetically when the overflow opens
// @version 0.1.0-dev.6
// @author HHeitlager
// @github https://github.com/hheitlager
// @homepage https://www.hendrikheitlager.nl/
// @include explorer.exe
// @architecture x86-64
// @compilerOptions -lole32 -loleaut32 -lruntimeobject -lversion
// @license GPL-3.0-only
// ==/WindhawkMod==
// Derived from Tray Overflow List 0.1.8.8 by HeyOkay (GPL-3.0-only).
// https://github.com/HeyOkay/TrayOverflowList
// Its derived helpers credit Ris Peng and m417z's tray mods.
// ==WindhawkModReadme==
/*
# Tray Overflow Sort

Automatically sorts hidden tray icons by application name whenever the hidden
icons popup opens. Works with the native Windows 11 grid and has also been
tested alongside Tray Overflow List and Tray Hover Expand.

## Sort order

- **Name #, A-Z** (default): ascending names, ignoring case.
- **Name #, Z-A**: descending names, ignoring case.

Digit-leading names come first in either direction. Digits are compared as text
(for example, 10 precedes 2 ascending). Equal names keep their relative order;
unnamed icons go last. Common .Root, .App, and .Runner suffixes are ignored.

Names prefer the application friendly name, then the automation name, then the
tooltip. This mod changes the order, not the displayed names or popup layout.
Icons added while the popup is open are sorted on its next opening. Reopen the
popup after changing the sort order. Disabling the mod leaves the current order
in place; it does not restore a previous order.

## Compatibility

Windows 11 x64. Uses internal shell symbols, so Windows updates can affect
compatibility. Debug logging reports sorting results and failures. If the tray
behaves incorrectly, disable this mod and restart Explorer.
*/
// ==/WindhawkModReadme==
// ==WindhawkModSettings==
/*
- sortOrder: name-ascending
  $name: Sort order
  $description: Sort hidden tray icons when the popup opens. Numbers come first in either direction.
  $options:
  - name-ascending: "Name #, A-Z"
  - name-descending: "Name #, Z-A"
*/
// ==/WindhawkModSettings==
#include <windhawk_utils.h>
#include <algorithm>
#include <atomic>
#include <cwctype>
#include <cwchar>
#include <cstdint>
#include <string>
#include <string_view>
#include <utility>
#include <vector>
#undef GetCurrentTime
#include <winrt/Windows.Foundation.Collections.h>
#include <winrt/Windows.UI.Xaml.Controls.h>
#include <winrt/Windows.UI.Xaml.Markup.h>
#include <winrt/Windows.UI.Xaml.Media.h>
#include <winrt/Windows.UI.Xaml.h>
using namespace winrt::Windows::UI::Xaml;
namespace wf = winrt::Windows::Foundation;
std::atomic<bool> g_unloading;
enum class SortOrder { Ascending, Descending };
SortOrder g_sortOrder = SortOrder::Ascending;
constexpr std::wstring_view kNameSuffixes[]{L".Root", L".App", L".Runner"};

std::wstring Trim(std::wstring_view s) {
    size_t begin = 0;
    size_t end = s.size();
    while (begin < end && iswspace(s[begin])) {
        begin++;
    }
    while (end > begin && iswspace(s[end - 1])) {
        end--;
    }
    return std::wstring(s.substr(begin, end - begin));
}

// Only remove explicit dot-delimited suffixes at the end. Never infer
// word boundaries, strip arbitrary extensions, or return an empty label.
std::wstring CleanTrayName(std::wstring name) {
    bool removed;
    do {
        removed = false;
        for (auto const& suffix : kNameSuffixes) {
            if (name.size() <= suffix.size())
                continue;
            auto tail = name.data() + name.size() - suffix.size();
            if (CompareStringOrdinal(
                    tail, static_cast<int>(suffix.size()), suffix.data(),
                    static_cast<int>(suffix.size()), TRUE) == CSTR_EQUAL) {
                auto candidate = Trim(std::wstring_view(
                    name.data(), name.size() - suffix.size()));
                if (candidate.empty())
                    continue;
                name = std::move(candidate);
                removed = true;
                break;
            }
        }
    } while (removed);
    return name;
}
// Collapse line breaks and repeated spaces in names supplied by applications.
std::wstring NormalizeName(std::wstring_view s) {
    std::wstring result;
    result.reserve(s.size());
    bool lastWasSpace = false;
    for (WCHAR c : s) {
        if (iswspace(c)) {
            if (!lastWasSpace) {
                result.push_back(L' ');
            }
            lastWasSpace = true;
        } else {
            result.push_back(c);
            lastWasSpace = false;
        }
    }
    return Trim(result);
}

constexpr GUID IID_INotificationAreaIcon6 = {
    0xD76CAD80,
    0x3103,
    0x54F4,
    {0x9A, 0xBE, 0x5F, 0x04, 0x7C, 0xBF, 0xE8, 0x5C}};
constexpr int kNotificationAreaIcon6_get_AppFriendlyName = 6;

// Resolved from symbols.
GUID* g_iconConfigurationIid;
void* g_iconConfigurationVftable;
void* g_iconConfiguration_get_DataModel;
GUID* g_notificationAreaIconsDataModelIid;
void* g_notificationAreaIconsDataModelVftable;
void* g_notificationAreaIconsDataModel_get_UDKObject;
GUID* g_iconContentViewModelIid;
void* g_imageContentViewModelBaseVftable;
void* g_imageContentViewModel_get_ToolTipText;
GUID* g_imageContentViewModelIid;
void* g_imageContentViewModelVftable;
void* g_imageContentViewModel_get_AutomationPropertyName;

Markup::IXamlMember GetXamlMember(PCWSTR typeName, PCWSTR memberName) {
    auto provider =
        Application::Current().try_as<Markup::IXamlMetadataProvider>();
    if (!provider) {
        return nullptr;
    }
    auto xamlType = provider.GetXamlType(typeName);
    if (!xamlType) {
        return nullptr;
    }
    return xamlType.GetMember(memberName);
}

// Queries an interface of an internal SystemTray.dll type. The result is only
// returned if it's backed by the expected implementation vtable, which makes
// calling that implementation's methods, resolved from symbols, on it safe.
winrt::com_ptr<IUnknown> QueryVerifiedInterface(wf::IInspectable const& object,
                                                GUID const* iid,
                                                void* expectedVftable) {
    winrt::com_ptr<IUnknown> result;
    if (!object || !iid || !expectedVftable) {
        return result;
    }
    ((IUnknown*)winrt::get_abi(object))
        ->QueryInterface(*iid, result.put_void());
    if (result && *(void**)result.get() != expectedVftable) {
        result = nullptr;
    }
    return result;
}

void* CallAbiGetter(IUnknown* object, void* getter) {
    void* value = nullptr;
    HRESULT hr = ((HRESULT(WINAPI*)(void*, void**))getter)(object, &value);
    return SUCCEEDED(hr) ? value : nullptr;
}

std::wstring CallStringGetter(IUnknown* object, void* getter) {
    winrt::hstring value;
    winrt::attach_abi(value, CallAbiGetter(object, getter));
    return NormalizeName(value);
}

// The app name comes from the executable, so it stays the same regardless of
// what the app puts in its tooltip.
std::wstring ReadAppName(wf::IInspectable const& viewModel) {
    if (!g_iconConfiguration_get_DataModel ||
        !g_notificationAreaIconsDataModel_get_UDKObject) {
        return {};
    }

    auto configurationMember =
        GetXamlMember(L"SystemTray.IconViewModel", L"Configuration");
    if (!configurationMember) {
        return {};
    }

    wf::IInspectable configuration{nullptr};
    try {
        configuration = configurationMember.GetValue(viewModel);
    } catch (...) {
        return {};
    }

    auto configurationInterface = QueryVerifiedInterface(
        configuration, g_iconConfigurationIid, g_iconConfigurationVftable);
    if (!configurationInterface) {
        return {};
    }

    wf::IInspectable dataModel{nullptr};
    winrt::attach_abi(dataModel,
                      CallAbiGetter(configurationInterface.get(),
                                    g_iconConfiguration_get_DataModel));

    auto dataModelInterface =
        QueryVerifiedInterface(dataModel, g_notificationAreaIconsDataModelIid,
                               g_notificationAreaIconsDataModelVftable);
    if (!dataModelInterface) {
        return {};
    }

    wf::IInspectable udkIcon{nullptr};
    winrt::attach_abi(
        udkIcon, CallAbiGetter(dataModelInterface.get(),
                               g_notificationAreaIconsDataModel_get_UDKObject));
    if (!udkIcon) {
        return {};
    }

    // Public interface, no vtable verification needed.
    winrt::com_ptr<IUnknown> icon6;
    ((IUnknown*)winrt::get_abi(udkIcon))
        ->QueryInterface(IID_INotificationAreaIcon6, icon6.put_void());
    if (icon6) {
        void* getter =
            (*(void***)icon6.get())[kNotificationAreaIcon6_get_AppFriendlyName];
        return CallStringGetter(icon6.get(), getter);
    }
    return {};
}

// Prefer a stable friendly name; only query fallback names when needed.
std::wstring ReadIconName(wf::IInspectable const& viewModel) {
    if (auto name = ReadAppName(viewModel); !name.empty()) {
        return CleanTrayName(std::move(name));
    }
    auto member = GetXamlMember(L"SystemTray.IconViewModel", L"ContentVM");
    if (!member) return {};
    auto content = member.GetValue(viewModel);
    if (g_imageContentViewModel_get_AutomationPropertyName) {
        auto image = QueryVerifiedInterface(content, g_imageContentViewModelIid,
                                             g_imageContentViewModelVftable);
        if (image) {
            auto name = CallStringGetter(image.get(),
                g_imageContentViewModel_get_AutomationPropertyName);
            if (!name.empty()) return CleanTrayName(std::move(name));
        }
    }
    if (g_imageContentViewModel_get_ToolTipText) {
        auto base = QueryVerifiedInterface(content, g_iconContentViewModelIid,
                                            g_imageContentViewModelBaseVftable);
        if (base) return CleanTrayName(CallStringGetter(base.get(),
            g_imageContentViewModel_get_ToolTipText));
    }
    return {};
}

FrameworkElement FindDescendantByName(DependencyObject const& element,
                                      std::wstring_view name) {
    int count = Media::VisualTreeHelper::GetChildrenCount(element);
    for (int i = 0; i < count; i++) {
        auto child = Media::VisualTreeHelper::GetChild(element, i);
        if (auto frameworkElement = child.try_as<FrameworkElement>()) {
            if (frameworkElement.Name() == name) {
                return frameworkElement;
            }
        }
        if (auto found = FindDescendantByName(child, name)) {
            return found;
        }
    }
    return nullptr;
}

void SortOverflowIcons(Controls::Control const& root) {
    static thread_local bool busy = false;
    if (!root || g_unloading || busy) return;
    struct BusyScope {
        bool& flag;
        explicit BusyScope(bool& value) : flag(value) { flag = true; }
        ~BusyScope() { flag = false; }
    } scope(busy);
    auto items = FindDescendantByName(root, L"OverflowItemsControl")
                     .try_as<Controls::ItemsControl>();
    if (!items) {
        Wh_Log(L"TOS: OverflowItemsControl not ready; reopen the popup");
        return;
    }
    using namespace winrt::Windows::Foundation::Collections;
    auto source = items.ItemsSource();
    auto collection = items.Items();
    struct Entry { std::wstring name; wf::IInspectable object; };
    std::vector<Entry> entries;
    std::vector<wf::IInspectable> original;
    for (uint32_t i = 0; i < collection.Size(); ++i) {
        try {
            auto object = collection.GetAt(i);
            entries.push_back({ReadIconName(object), object});
            original.push_back(object);
        } catch (winrt::hresult_error const& e) {
            Wh_Log(L"TOS: item %u failed HRESULT=%08X", i + 1, (unsigned)e.code().value);
        } catch (...) { Wh_Log(L"TOS: item %u failed", i + 1); }
    }
    std::stable_sort(entries.begin(), entries.end(), [](auto const& a, auto const& b) {
        if (a.name.empty() != b.name.empty()) return !a.name.empty();
        bool aDigit = !a.name.empty() && a.name[0] >= L'0' && a.name[0] <= L'9';
        bool bDigit = !b.name.empty() && b.name[0] >= L'0' && b.name[0] <= L'9';
        if (aDigit != bDigit) return aDigit;
        int comparison = CompareStringOrdinal(a.name.c_str(), -1, b.name.c_str(), -1, TRUE);
        return comparison == (g_sortOrder == SortOrder::Descending
                                  ? CSTR_GREATER_THAN : CSTR_LESS_THAN);
    });
    auto vector = source ? source.try_as<IVector<wf::IInspectable>>() : nullptr;
    if (!vector || original.size() != collection.Size() || original.size() != vector.Size()) {
        Wh_Log(L"TOS: SKIP: unsupported source or incomplete snapshot");
        return;
    }
    auto matches = [&](std::vector<wf::IInspectable> const& expected) {
        if (vector.Size() != expected.size()) return false;
        for (uint32_t i = 0; i < vector.Size(); ++i)
            if (vector.GetAt(i) != expected[i]) return false;
        return true;
    };
    std::vector<wf::IInspectable> sorted;
    for (size_t i = 0; i < entries.size(); ++i) {
        sorted.push_back(entries[i].object);
    }
    if (!matches(original)) {
        Wh_Log(L"TOS: SKIP: source changed during name lookup");
        return;
    }
    if (matches(sorted)) {
        Wh_Log(L"TOS: ALREADY SORTED; no write needed");
        return;
    }
    try {
        // One reset notification, preserving each existing view-model object.
        vector.ReplaceAll(winrt::array_view<wf::IInspectable const>(sorted));
        if (matches(sorted)) {
            Wh_Log(L"TOS: APPLIED and verified %u icons", (unsigned)sorted.size());
            return;
        }
        Wh_Log(L"TOS: VERIFY FAILED: Explorer did not retain requested order");
    } catch (winrt::hresult_error const& e) {
        Wh_Log(L"TOS: WRITE FAILED HRESULT=%08X", (unsigned)e.code().value);
    } catch (...) {
        Wh_Log(L"TOS: WRITE FAILED: unknown exception");
    }
    // Do not overwrite an application arriving/departing in a reentrant callback.
    try {
        if (matches(original)) {
            Wh_Log(L"TOS: original order intact");
            return;
        }
        if (vector.Size() != original.size()) {
            Wh_Log(L"TOS: rollback skipped: membership changed");
            return;
        }
        std::vector<bool> seen(original.size(), false);
        for (uint32_t i = 0; i < vector.Size(); ++i) {
            auto current = vector.GetAt(i);
            size_t j = 0;
            for (; j < original.size(); ++j)
                if (!seen[j] && current == original[j]) break;
            if (j == original.size()) {
                Wh_Log(L"TOS: rollback skipped: membership changed");
                return;
            }
            seen[j] = true;
        }
        vector.ReplaceAll(winrt::array_view<wf::IInspectable const>(original));
        Wh_Log(L"TOS: rollback verified=%d", matches(original));
    } catch (...) {
        Wh_Log(L"TOS: rollback failed; disable mod and restart Explorer");
    }
}
thread_local bool showing = false;
using Show_t = void(WINAPI*)(void*, POINT, int);
Show_t ShowOriginal;
void WINAPI ShowHook(void* self, POINT pt, int kind) {
    struct ShowingScope {
        bool previous = std::exchange(showing, true);
        ~ShowingScope() { showing = previous; }
    } scope;
    ShowOriginal(self, pt, kind);
}
using Measure_t = void(WINAPI*)(void*, wf::Size const*);
Measure_t MeasureOriginal;
void WINAPI MeasureHook(void* self, wf::Size const* size) {
    MeasureOriginal(self, size);
    if (showing && !g_unloading)
        try {
            auto root = reinterpret_cast<wf::IInspectable const*>(self)
                            ->try_as<Controls::Control>();
            if (root) {
                SortOverflowIcons(root);
            }
        } catch (...) {
            Wh_Log(L"TOS: overflow sorting failed");
        }
}

VS_FIXEDFILEINFO* GetModuleVersionInfo(HMODULE hModule) {
    void* pFixedFileInfo = nullptr;
    UINT uPtrLen = 0;

    HRSRC hResource =
        FindResource(hModule, MAKEINTRESOURCE(VS_VERSION_INFO), RT_VERSION);
    if (hResource) {
        HGLOBAL hGlobal = LoadResource(hModule, hResource);
        if (hGlobal) {
            void* pData = LockResource(hGlobal);
            if (pData) {
                if (!VerQueryValue(pData, L"\\", &pFixedFileInfo, &uPtrLen) ||
                    uPtrLen == 0) {
                    pFixedFileInfo = nullptr;
                    uPtrLen = 0;
                }
            }
        }
    }

    return (VS_FIXEDFILEINFO*)pFixedFileInfo;
}

HMODULE GetSystemTrayModuleHandle() {
    HMODULE module = GetModuleHandle(L"SystemTray.dll");
    if (!module) {
        module = GetModuleHandle(L"Taskbar.View.dll");
        if (module) {
            // Newer Taskbar.View.dll versions no longer contain the tray.
            VS_FIXEDFILEINFO* fixedFileInfo =
                GetModuleVersionInfo(module);
            WORD moduleMajor =
                fixedFileInfo ? HIWORD(fixedFileInfo->dwFileVersionMS) : 0;
            if (!moduleMajor || moduleMajor >= 2604) {
                module = nullptr;
            }
        }
    }

    return module;
}

std::atomic<bool> g_systemTrayModuleHooked;

bool HookSystemTraySymbols(HMODULE module) {
    // clang-format off
    // SystemTray.dll, Taskbar.View.dll
    WindhawkUtils::SYMBOL_HOOK symbolHooks[] = {
        {
            {LR"(public: void __cdecl winrt::SystemTray::OverflowXamlIslandManager::Show(struct tagPOINT,enum winrt::WindowsUdk::UI::Shell::InputDeviceKind))"},
            &ShowOriginal,
            ShowHook,
        },
        {
            {LR"(public: __cdecl winrt::impl::consume_Windows_UI_Xaml_IUIElement<struct winrt::SystemTray::NotificationAreaOverflow>::Measure(struct winrt::Windows::Foundation::Size const &)const )"},
            &MeasureOriginal,
            MeasureHook,
        },
        {
            {LR"(struct guid::guid const winrt::impl::guid_v<struct winrt::SystemTray::IIconConfiguration>)"},
            &g_iconConfigurationIid,
            nullptr,
            true,
        },
        {
            {LR"(const winrt::impl::produce<struct winrt::SystemTray::implementation::IconConfiguration,struct winrt::SystemTray::IIconConfiguration>::`vftable')"},
            &g_iconConfigurationVftable,
            nullptr,
            true,
        },
        {
            {LR"(public: virtual int __cdecl winrt::impl::produce<struct winrt::SystemTray::implementation::IconConfiguration,struct winrt::SystemTray::IIconConfiguration>::get_DataModel(void * *))"},
            &g_iconConfiguration_get_DataModel,
            nullptr,
            true,
        },
        {
            {LR"(struct guid::guid const winrt::impl::guid_v<struct winrt::SystemTray::INotificationAreaIconsDataModel>)"},
            &g_notificationAreaIconsDataModelIid,
            nullptr,
            true,
        },
        {
            {LR"(const winrt::impl::produce<struct winrt::SystemTray::implementation::NotificationAreaIconsDataModel,struct winrt::SystemTray::INotificationAreaIconsDataModel>::`vftable')"},
            &g_notificationAreaIconsDataModelVftable,
            nullptr,
            true,
        },
        {
            {LR"(public: virtual int __cdecl winrt::impl::produce<struct winrt::SystemTray::implementation::NotificationAreaIconsDataModel,struct winrt::SystemTray::INotificationAreaIconsDataModel>::get_UDKObject(void * *))"},
            &g_notificationAreaIconsDataModel_get_UDKObject,
            nullptr,
            true,
        },
        {
            {LR"(struct guid::guid const winrt::impl::guid_v<struct winrt::SystemTray::IIconContentViewModel>)"},
            &g_iconContentViewModelIid,
            nullptr,
            true,
        },
        {
            {LR"(const winrt::impl::produce<struct winrt::SystemTray::implementation::ImageIconContentViewModel,struct winrt::SystemTray::IIconContentViewModel>::`vftable')"},
            &g_imageContentViewModelBaseVftable,
            nullptr,
            true,
        },
        {
            {LR"(public: virtual int __cdecl winrt::impl::produce<struct winrt::SystemTray::implementation::ImageIconContentViewModel,struct winrt::SystemTray::IIconContentViewModel>::get_ToolTipText(void * *))"},
            &g_imageContentViewModel_get_ToolTipText,
            nullptr,
            true,
        },
        {
            {LR"(struct guid::guid const winrt::impl::guid_v<struct winrt::SystemTray::IImageIconContentViewModel>)"},
            &g_imageContentViewModelIid,
            nullptr,
            true,
        },
        {
            {LR"(const winrt::impl::produce<struct winrt::SystemTray::implementation::ImageIconContentViewModel,struct winrt::SystemTray::IImageIconContentViewModel>::`vftable')"},
            &g_imageContentViewModelVftable,
            nullptr,
            true,
        },
        {
            {LR"(public: virtual int __cdecl winrt::impl::produce<struct winrt::SystemTray::implementation::ImageIconContentViewModel,struct winrt::SystemTray::IImageIconContentViewModel>::get_AutomationPropertyName(void * *))"},
            &g_imageContentViewModel_get_AutomationPropertyName,
            nullptr,
            true,
        },
    };

    // clang-format on

    if (!WindhawkUtils::HookSymbols(module, symbolHooks,
                                    ARRAYSIZE(symbolHooks))) {
        Wh_Log(L"HookSymbols failed");
        return false;
    }

    bool appNames = g_iconConfigurationIid && g_iconConfigurationVftable &&
                    g_iconConfiguration_get_DataModel &&
                    g_notificationAreaIconsDataModelIid &&
                    g_notificationAreaIconsDataModelVftable &&
                    g_notificationAreaIconsDataModel_get_UDKObject;
    bool toolTips = g_iconContentViewModelIid &&
                    g_imageContentViewModelBaseVftable &&
                    g_imageContentViewModel_get_ToolTipText;
    bool names = g_imageContentViewModelIid && g_imageContentViewModelVftable &&
                 g_imageContentViewModel_get_AutomationPropertyName;
    Wh_Log(L"Icon names: app=%d tooltip=%d name=%d", appNames, toolTips, names);

    if (!appNames) {
        Wh_Log(L"App name matching unavailable");
    }

    if (!toolTips && !names) {
        Wh_Log(L"Couldn't find the icon tooltip getters");
        return false;
    }

    return true;
}

void HandleLoadedModuleIfSystemTray(HMODULE module, LPCWSTR lpLibFileName) {
    if (!g_systemTrayModuleHooked && GetSystemTrayModuleHandle() == module &&
        !g_systemTrayModuleHooked.exchange(true)) {
        Wh_Log(L"Loaded %s", lpLibFileName);

        if (HookSystemTraySymbols(module)) {
            Wh_ApplyHookOperations();
        }
    }
}

using LoadLibraryExW_t = decltype(&LoadLibraryExW);
LoadLibraryExW_t LoadLibraryExW_Original;
HMODULE WINAPI LoadLibraryExW_Hook(LPCWSTR lpLibFileName,
                                   HANDLE hFile,
                                   DWORD dwFlags) {
    HMODULE module = LoadLibraryExW_Original(lpLibFileName, hFile, dwFlags);
    if (module) {
        HandleLoadedModuleIfSystemTray(module, lpLibFileName);
    }

    return module;
}

// Mod lifecycle

void LoadSettings() {
    auto order = WindhawkUtils::StringSetting::make(L"sortOrder");
    g_sortOrder = wcscmp(order.get(), L"name-descending") == 0 ? SortOrder::Descending
        : SortOrder::Ascending;
    Wh_Log(L"TOS: sort order=%s; applied on popup opening", order.get());
}

BOOL Wh_ModSettingsChanged(BOOL* reload) {
    // Reload so settings are immutable while the tray thread is sorting.
    *reload = TRUE;
    return TRUE;
}

BOOL Wh_ModInit() {
    LoadSettings();

    if (HMODULE systemTrayModule = GetSystemTrayModuleHandle()) {
        g_systemTrayModuleHooked = true;
        if (!HookSystemTraySymbols(systemTrayModule)) {
            return FALSE;
        }
    } else {
        Wh_Log(L"System tray module not loaded yet");

        HMODULE kernelBaseModule = GetModuleHandle(L"kernelbase.dll");
        auto pKernelBaseLoadLibraryExW =
            (decltype(&LoadLibraryExW))GetProcAddress(kernelBaseModule,
                                                      "LoadLibraryExW");
        if (!pKernelBaseLoadLibraryExW ||
            !WindhawkUtils::SetFunctionHook(pKernelBaseLoadLibraryExW,
                                            LoadLibraryExW_Hook,
                                            &LoadLibraryExW_Original)) {
            Wh_Log(L"Couldn't hook LoadLibraryExW");
            return FALSE;
        }
    }

    return TRUE;
}

void Wh_ModAfterInit() {

    if (!g_systemTrayModuleHooked) {
        if (HMODULE systemTrayModule = GetSystemTrayModuleHandle()) {
            if (!g_systemTrayModuleHooked.exchange(true)) {
                if (HookSystemTraySymbols(systemTrayModule)) {
                    Wh_ApplyHookOperations();
                }
            }
        }
    }
}

void Wh_ModBeforeUninit() {
    g_unloading = true;
}
